import React from "react";
import {Select as DefaultSelect, Styles} from "@dashthis/ui";
import {selectStyle} from "./styles/select.style";

interface IProps<T> extends DefaultSelect.Types.ISelectProps<T> {
}

export const Select = <T extends {}>(props: IProps<T>) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, selectStyle);

  return (
    <DefaultSelect.Select {...props} className={css}/>
  );
};


export default Select;
