import React from "react";
import {Dialog, Menu as DefaultMenu} from "@dashthis/ui";
import {Menu} from "../../../../../../components";
import formatMessage from "format-message";
import {UserModel} from "../../../../../../models/User";
import {useOpenUrlServiceContext} from "../../../../../../services/hooks/useOpenUrlServiceContext";
import {useEmulateAccount} from "../../../../hooks/useEmulateAccount";
import {useCopyToClipboard} from "../../../../../../hooks/useCopyToClipboard";

interface IProps {
  user: UserModel;
  emulateUser: (user: UserModel) => void;
  hideMenu: () => void;
  forcePassword: (password: string) => void;
}

export const AccountUserActionMenu = (props: IProps) => {
  const {user, emulateUser: emulateUserProp, hideMenu, forcePassword} = props;
  const {openUrl} = useOpenUrlServiceContext();
  const copyToClipboard = useCopyToClipboard();
  const {emulateUserInBrowserWindow, emulateUser, emulateUrl} = useEmulateAccount();
  const handleEmulateUser = () => {
    hideMenu();
    emulateUserProp(user);
  };
  const handleEmulateAccountInWindow = () => {
    hideMenu();
    emulateUser(user);
  };
  const handleEmulateInBrowser = () => {
    hideMenu();
    emulateUserInBrowserWindow(user);
  };
  const handleOpenUserInHubSpot = () => {
    hideMenu();
    openUrl(user.hubSpotUri!);
  };
  const handleCopyToClipboard = () => {
    hideMenu();
    copyToClipboard(emulateUrl(user));
  };
  const handleForcePassword = () => {
    hideMenu();
    Dialog.ApplicationDialogs.prompt({
      title: formatMessage("Force user password"),
      message: formatMessage("Enter a new password for this user."),
      okText: formatMessage("Apply"),
      okClick: (value) => forcePassword(value)
    });
  };

  return (
    <Menu.Menu>
      <DefaultMenu.MenuItem onClick={handleEmulateUser}>{formatMessage("Emulate")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem onClick={handleEmulateAccountInWindow}>{formatMessage("Emulate In New Window")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem onClick={handleEmulateInBrowser}>{formatMessage("Emulate In Browser")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuItem onClick={handleCopyToClipboard}>{formatMessage("Copy Emulate Link")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator/>
      <DefaultMenu.MenuItem onClick={handleForcePassword}>{formatMessage("Force New Password")}</DefaultMenu.MenuItem>
      <DefaultMenu.MenuSeparator/>
      <DefaultMenu.MenuItem onClick={handleOpenUserInHubSpot} disabled={user.hubSpotUri == null}>{formatMessage("Open User In HubSpot")}</DefaultMenu.MenuItem>
    </Menu.Menu>
  );
};

export default AccountUserActionMenu;
