import React, {Fragment} from "react";
import {HeaderItem} from "../HeaderItem";
import formatMessage from "format-message";
import {AccountItem} from "../Accounts/AccountItem";
import {DashboardItem} from "./DashboardItem";
import {AccountModel} from "../../../../../../models/Account";
import {OpenAccounts, OpenDashboard} from "../../../../../../states/actions";
import {Styles} from "@dashthis/ui";
import {dashboardsStyle} from "./styles/dashboardItem.style";
import {DashboardModel} from "../../../../../../models/Dashboard";

interface IProps {
  /**
   * The list of account to display.
   */
  accounts: AccountModel[];
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  /**
   * Count of account found
   */
  count: number;
  /**
   * Number of total account found
   */
  total: number;
  /**
   *
   */
  openDashboard: OpenDashboard;
}

export const Dashboards = (props: IProps) => {
  const {accounts, openAccounts, count, total, openDashboard} = props;
  const handleAccountDoubleClick = (account: AccountModel, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    openAccounts(new Set([account.id!]));
  };
  const handleDashboardDoubleClick = (account: AccountModel, dashboard: DashboardModel) => (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    openDashboard(account.id!, dashboard.id!);
  };
  const css = Styles.Hooks.useClassName(dashboardsStyle);

  return (
    <Fragment>
      <HeaderItem total={total} count={count} title={formatMessage("Dashboards")}/>
      {accounts.map((account) => (
        <AccountItem className={css} onDoubleClick={handleAccountDoubleClick} account={account} key={account.id!}>
          {account.Dashboards.map((dashboard) => (
            <DashboardItem onDoubleClick={handleDashboardDoubleClick(account, dashboard)} key={dashboard.id!} dashboard={dashboard}/>
          ))}
        </AccountItem>
      ))}
    </Fragment>
  );
};


export default Dashboards;
