import React from "react";
import {Line} from "react-chartjs-2";
import dayjs from "dayjs";
import {IStudioTheme} from "../../../../../../../styles/studioTheme";
import {Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {healthGraphStyle, healthGraphTitleStyle} from "./styles/healthGraph.style";
import {DashboardViewedModel} from "../../../../../../../models/DashboardViewed";

interface IProps {
  /**
   * Array contains usage stats.
   */
  stats: DashboardViewedModel[];
}

const formatData = (stats: DashboardViewedModel[]) => {
  const labels = stats.map((s) => dayjs(s.date).format("MMM D"));
  const viewed = stats.map((s) => s.view);
  const theme = Styles.Hooks.useTheme<IStudioTheme>();

  return {
    labels,
    datasets: [{
      label: formatMessage("View"),
      fill: false,
      data: viewed,
      precision: 0,
      borderColor: theme.colors.primary.rgb().string()
    }]
  };
};
const graphOptions = {
  maintainAspectRatio: true,
  scales: {
    xAxes: [{
      display: true,
      ticks: {
        callback: (dataLabel: string, index: number) => {
          return index % 2 === 0 ? dataLabel : "";
        }
      }
    }],
    yAxes: [{
      ticks: {
        stepSize: 2
      }
    }]
  }
};

export const AccountDashboardViewed = React.memo<IProps>((props) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{formatMessage("End Users View")}</span>
      <Line
        height={100}
        data={formatData(stats)}
        options={graphOptions}
      />
    </div>
  );
});


export default AccountDashboardViewed;
