import React from "react";
import {Stack, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {MostViewedDashboardsModel} from "../../../../../../models/MostViewedDashboards";
import {healthGraphStyle, healthGraphTitleStyle} from "../Dashboards/Health/styles/healthGraph.style";
import {mostViewedDashboardsDashboardLetterStyle} from "./styles/mostViewedDashboards.style";

interface IProps {
  /**
   *
   */
  stats: MostViewedDashboardsModel[];
}

export const MostViewedDashboards = (props: IProps) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const dashboardLetterCss = Styles.Hooks.useClassName(mostViewedDashboardsDashboardLetterStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);
  const getRows = () => {
    return stats.map((s) => (
      <Stack.HStack key={s.Dashboard!.id!}>
        <Stack.StackItem as="div" itemSize="1fr">
          <span style={{color: s.Dashboard!.DashboardType!.color}} className={dashboardLetterCss}>{s.Dashboard!.DashboardType!.dashboardTypeLetter}</span>
          {s.Dashboard!.title}
        </Stack.StackItem>
        <Stack.StackItem as="div" itemSize="auto">{s.view}</Stack.StackItem>
      </Stack.HStack>
    ));
  };

  if (stats.length === 0) {
    return null;
  }

  return (
    <div className={css}>
      <Stack.HStack>
        <Stack.StackItem as="div" itemSize="1fr" className={titleCss}>{formatMessage("Most dashboard viewed by end user")}</Stack.StackItem>
        <Stack.StackItem as="div" itemSize="auto" className={titleCss}>{formatMessage("Total viewed")}</Stack.StackItem>
      </Stack.HStack>
      {getRows()}
    </div>
  );
};

export default MostViewedDashboards;
