import {StudioCSS} from "../../../../../../styles/types";

export const addFilterButtonStyle: StudioCSS = (theme, utilities) => ({
  label: "add-filter-button",
  display: "inline-grid",
  margin: `${utilities.space("s")} ${utilities.space("l")}`,
  alignItems: "center",
  gridTemplateColumns: "auto 1fr",
  gap: utilities.space("t"),
  transition: "color .3sec",
  ...utilities.fontStyle({
    size: "small",
    color: "secondary"
  }),
  "&:hover": {
    cursor: "pointer",
    ...utilities.fontStyle({
      color: "secondaryDark"
    })
  }
});

export const addFilterButtonAddIconStyle: StudioCSS = (theme, utilities) => ({
  label: "add-filter-button-add-icon",
  width: 12,
  height: 12
});
