import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import {SearchField} from "../../../../../../components";
import {useListAccountFileTemplates} from "./hooks/useListAccountFileTemplates";
import {QueryProcessor, Styles} from "@dashthis/ui";
import FileTemplatesList from "./list/FileTemplatesList";
import {fileTemplatesStyle} from "./styles/fileTemplates.style";
import formatMessage from "format-message";
import {useAccountPersistedState} from "../../hooks/useAccountPersistedState";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const FileTemplates = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesStyle);
  const {error, loading, fileTemplates} = useListAccountFileTemplates(account.id!);
  const [query, setQuery] = useAccountPersistedState<string>(`fileTemplatesSearch`, "");
  const onSearchChange = (value: string) => {
    setQuery(value);
  };
  const handleClearOnClick = () => {
    setQuery("");
  };

  return (
    <QueryProcessor.QueryProcessor loading={loading} error={error}>
      <div className={css}>
        <SearchField.SearchField delayOnChange={400} defaultValue={query} onDelayChange={onSearchChange} clearOnClick={handleClearOnClick} placeholder={formatMessage("Search for file templates...")}/>
        <FileTemplatesList
          query={query}
          account={account}
          fileTemplates={fileTemplates}
        />
      </div>
    </QueryProcessor.QueryProcessor>
  );
};

export default FileTemplates;
