import React from "react";
import {Stack, Styles} from "@dashthis/ui";
import {accountLoadingBarStyle, accountLoadingGraphStyle, accountLoadingStyle, accountLoadingToolbarStyle} from "./styles/accountLoading.style";
import PlaceholderLoading from "react-placeholder-loading";
import {accountHeaderInfoContainerStyle} from "./components/Header/styles/accountHeader.style";

interface IProps {

}

export const AccountLoading = (props: IProps) => {
  const css = Styles.Hooks.useClassName(accountLoadingStyle);
  const barCss = Styles.Hooks.useClassName(accountLoadingBarStyle);
  const graphCss = Styles.Hooks.useClassName(accountLoadingGraphStyle);
  const toolbarCss = Styles.Hooks.useClassName(accountLoadingToolbarStyle);
  const infoContainerCss = Styles.Hooks.useClassName(accountHeaderInfoContainerStyle);
  const colorStart = "#EDF1F5";
  const colorEnd = "#F4F6F9";

  return (
    <Stack.HStack as="div" className={css}>
      <Stack.StackItem as="div" className={`${toolbarCss} ${barCss}`} itemSize="50px"/>
      <Stack.StackItem as={Stack.VStack} itemSize="1fr">
        <Stack.StackItem className={infoContainerCss} as="div" itemSize="115px">
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={260}/>
          <div/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={120}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={170}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={260}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={150}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={190}/>
          <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={130}/>
        </Stack.StackItem>
        <Stack.StackItem as="div" className={barCss} itemSize="38px"/>
        <Stack.StackItem className={graphCss} as={Stack.VStack} gap={30} itemSize="1fr">
          <Stack.StackItem as={Stack.HStack} gap={10}>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={85} width={125}></Stack.StackItem>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={85} width={153}></Stack.StackItem>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={85} width={153}></Stack.StackItem>
            <Stack.StackItem as="div" itemSize="1fr"/>
          </Stack.StackItem>
          <Stack.StackItem gap={10} as={Stack.VStack}>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={125}></Stack.StackItem>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={190} width="100%"></Stack.StackItem>
          </Stack.StackItem>
          <Stack.StackItem gap={10} as={Stack.VStack}>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={16} width={160}></Stack.StackItem>
            <Stack.StackItem as={PlaceholderLoading} colorStart={colorStart} colorEnd={colorEnd} shape={"rect"} height={160} width="100%"></Stack.StackItem>
          </Stack.StackItem>
        </Stack.StackItem>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export default AccountLoading;
