import React, {Fragment} from "react";
import ViewEditFileTemplateWindowSubHeader from "./ViewEditFileTemplateWindowSubHeader";
import formatMessage from "format-message";
import ViewEditFileTemplateWindowText from "./ViewEditFileTemplateWindowText";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowHeaderSectionStyle} from "./styles/fileTemplatesViewEditWindow.style";
import ViewEditFileTemplateWindowHeader from "./ViewEditFileTemplateWindowHeader";
import {CsvTemplateModel} from "../../../../../../../../models/CsvTemplate";
import ViewEditFileTemplateWindowInput from "./ViewEditFileTemplateWindowInput";
import {Field} from "formik";

interface IProps {
  /**
   * The csv template model.
   */
  csvTemplate: CsvTemplateModel;

}

export const ViewEditFileTemplateWindowHeaderSection = (props: IProps) => {
  const {csvTemplate} = props;
  const headerSectionCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowHeaderSectionStyle);
  const customerIdField = csvTemplate.getCustomerIdField();
  const dateField = csvTemplate.getDateField();
  const dateFieldIndex = csvTemplate.getDateFieldIndex();

  return (
    <Fragment>
      <ViewEditFileTemplateWindowHeader>{formatMessage("Header")}</ViewEditFileTemplateWindowHeader>
      <div className={headerSectionCss}>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Element")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("No Column")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("No Line")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Format")}</ViewEditFileTemplateWindowSubHeader>
        {customerIdField != null
          ? <Fragment>
            <ViewEditFileTemplateWindowText>{formatMessage("Customer Id")}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText>{customerIdField.columnIndex}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText>{customerIdField.lineIndex}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText/>
          </Fragment>
          : null
        }
        {dateField != null
          ? <Fragment>
            <ViewEditFileTemplateWindowText>{formatMessage("Date")}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText>{dateField.columnIndex}</ViewEditFileTemplateWindowText>
            <ViewEditFileTemplateWindowText>{dateField.lineIndex}</ViewEditFileTemplateWindowText>
            <Field name={`dataFields[${dateFieldIndex}].dataFormat`} as={ViewEditFileTemplateWindowInput}/>
          </Fragment>
          : null
        }
      </div>
    </Fragment>
  );
};


export default ViewEditFileTemplateWindowHeaderSection;
