import React from "react";
import {Button as DefaultButton, Styles} from "@dashthis/ui";
import {buttonStyle} from "./styles/button.style";

interface IProps extends DefaultButton.Types.IButtonProps {
}

export const Button = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, buttonStyle);

  return (
    <DefaultButton.Button {...props} size={DefaultButton.Enums.ButtonSizeEnum.Small} basic={false} className={css}/>
  );
};


export default Button;
