import React from "react";
import {Button as DefaultButton, Styles} from "@dashthis/ui";
import {buttonStyle, buttonDarkStyle} from "./styles/button.style";

interface IDarkButtonProps extends DefaultButton.Types.IButtonProps {
}

export const DarkButton = (props: IDarkButtonProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, buttonStyle, buttonDarkStyle);

  return (
    <DefaultButton.Button {...props} size={DefaultButton.Enums.ButtonSizeEnum.Small} basic={false} className={css}/>
  );
};


export default DarkButton;
