import gql from "graphql-tag";
import {InvoicePart} from "../fragments/invoice/invoicePart";
import {DocumentNode} from "graphql";

export const accountInvoicesQuery: DocumentNode = gql`
    query($id:ID!){
        account(id:$id){
            id
            invoices {
                ...InvoicePart
            }
        }
    }
    ${InvoicePart}
`;