import React, {HTMLAttributes} from "react";
import {Stack, Styles} from "@dashthis/ui";
import {navigationBarStyle} from "./styles/navigationBar.style";
import {INavigationBarItemProps} from "./NavigationBarItem";
import NavigationBarMore from "./NavigationBarMore";
import {useNavigationBarOverflow} from "./hooks/useNavigationBarOverflow";


interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  children: (React.ReactElement<INavigationBarItemProps> | null)[];
}

export const NavigationBar = (props: IProps) => {
  const {children, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, navigationBarStyle);
  const {className, itemsHide, itemsNotVisible, Provider} = useNavigationBarOverflow();

  return (
    <Provider>
      <Stack.VStack>
        <Stack.StackItem itemSize="auto" as="div" {...rest} className={`${css} ${className}`}>
          {children}
        </Stack.StackItem>
        {itemsHide && <Stack.StackItem items={itemsNotVisible} as={NavigationBarMore} itemSize="30px"/>}
      </Stack.VStack>
    </Provider>

  );
};


export default NavigationBar;
