import React from "react";
import {Styles} from "@dashthis/ui";
import {healthBoxStyle} from "./styles/healthBox.style";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../../models/Account";

interface IProps {
  /**
   * Component children.
   */
  account: AccountModel;
}

export const UsersUsage = (props: IProps) => {
  const css = Styles.Hooks.useClassName(healthBoxStyle);
  const {account} = props;
  const users = account.Users;

  return (
    <div className={css}>
      <span>{users.length}</span>
      <span>{formatMessage("Users")}</span>
    </div>
  );
};


export default UsersUsage;
