import React, {HTMLAttributes} from "react";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {HamburgerMenu, Stack, Styles, Tooltip} from "@dashthis/ui";
import {Conditional, Models} from "@dashthis/common";
import {Icon} from "../../../../../../../components";
import {accountDashboardsItemDateStyle, accountDashboardsItemEvenStyle, accountDashboardsItemLetterStyle, accountDashboardsItemOddStyle, accountDashboardsItemSelectedStyle, accountDashboardsItemStyle, accountDashboardsItemThemeIconStyle, accountDashboardsItemTitleContainerStyle, accountDashboardsItemTitleStyle} from "../styles/accountDashboardsItem.style";
import formatMessage from "format-message";
import AccountDashboardsMenuAction from "./AccountDashboardsMenuAction";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The dashboard Model
   */
  dashboard: DashboardModel
  /**
   * Indicate if row are odd and if true
   * draw white background
   */
  isOdd: boolean,
  /**
   * Indicate if item are selected
   */
  selected: boolean;
}

export const AccountDashboardsItem = (props: IProps) => {
  const {dashboard, isOdd, selected, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountDashboardsItemStyle,
    Conditional.is(isOdd, accountDashboardsItemOddStyle),
    Conditional.isNot(isOdd, accountDashboardsItemEvenStyle),
    Conditional.is(selected, accountDashboardsItemSelectedStyle)
  );
  const titleContainerCss = Styles.Hooks.useClassName(accountDashboardsItemTitleContainerStyle);
  const titleCss = Styles.Hooks.useClassName(accountDashboardsItemTitleStyle);
  const dateCss = Styles.Hooks.useClassName(accountDashboardsItemDateStyle);
  const letterCss = Styles.Hooks.useClassName(accountDashboardsItemLetterStyle, {
    color: dashboard.DashboardType!.color
  });
  const themeIconCss = Styles.Hooks.useClassName(accountDashboardsItemThemeIconStyle);
  const customizationTooltip = () => Models.ColorTheme.Utility.ColorThemeModelMatcher.colorThemeModelMatcher(dashboard.Customization(), {
    customThemeCustomization: () => formatMessage("This dashboard has custom color theme apply on it."),
    noCustomization: () => "",
    noMatch: () => "",
    presetThemeCustomization: () => formatMessage("This dashboard has preset color theme apply on it."),
    whiteLabelThemeCustomization: () => formatMessage("This dashboard has white label apply on it.")
  });

  return (
    <Stack.HStack alignItems={Stack.Enums.AlignItemsEnum.Center} gap={5} as="div" {...rest} className={css}>
      <Stack.StackItem itemSize="auto" as="span" className={letterCss}>{dashboard.DashboardType!.dashboardTypeLetter}</Stack.StackItem>
      <Stack.StackItem itemSize="1fr" as="div" className={titleContainerCss}>
        <span className={titleCss}>{dashboard.title}</span>
        <span className={dateCss}>{dashboard.lastAccessed}</span>
      </Stack.StackItem>
      {!dashboard.hasNoCustomizationApplyOnIt() && <Tooltip.Tooltip Reference={<Stack.StackItem itemSize="auto" as={Icon.Icons.CustomThemeIcon} className={themeIconCss}/>}>{customizationTooltip()}</Tooltip.Tooltip>}
      <HamburgerMenu.HamburgerMenu menu={({hideMenu}) => <AccountDashboardsMenuAction hideMenu={hideMenu} dashboard={dashboard}/>}/>
    </Stack.HStack>
  );
};


export default AccountDashboardsItem;
