import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardsSelectWidgetStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-select-widget",
  display: "flex",
  alignItems: "center",
  flexDirection: "column",
  justifyContent: "center",
  textTransform: "uppercase",
  padding: utilities.space("l"),
  textAlign: "center"
});

export const accountDashboardsSelectWidgetPlaceholderStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-select-widget-placeholder",
  width: 124,
  height: 81
});

export const accountDashboardsSelectWidgetTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-select-widget-title",
  ...utilities.fontStyle({
    weight: "m",
    size: "large"
  })
});

export const accountDashboardsSelectWidgetNoteStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-select-widget-note",
  textTransform: "none",
  paddingBottom: utilities.space("m"),
  ...utilities.fontStyle({
    weight: "n",
    color: "scorpion",
    size: "small"
  })
});

export const accountDashboardsSelectWidgetDescriptionStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboards-select-widget-description",
  paddingTop: utilities.space("m"),
  ...utilities.fontStyle({
    weight: "n",
    size: "regular"
  })
});
