import React from "react";
import {Stack, Styles} from "@dashthis/ui";
import {accountDashboardListContainerStyle, accountDashboardListFooterStyle, accountDashboardListSortContainerStyle} from "../styles/accountDashboardList.style";
import PlaceholderLoading from "react-placeholder-loading";
import {accountDashboardsItemStyle} from "../styles/accountDashboardsItem.style";

interface IProps {

}

const colorStart = "#EDF1F5";
const colorEnd = "#F4F6F9";

const ItemPlaceHolder = () => {
  const css = Styles.Hooks.useClassName(accountDashboardsItemStyle);

  return (
    <Stack.HStack gap={5} className={css} alignItems={Stack.Enums.AlignItemsEnum.Center}>
      <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={22} height={22} shape="rect"/>
      <Stack.StackItem itemSize="1fr" as={Stack.VStack} gap={5}>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={134} height={12} shape="rect"/>
        <PlaceholderLoading colorStart={colorStart} colorEnd={colorEnd} width={94} height={12} shape="rect"/>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export const AccountDashboardLoading = (props: IProps) => {
  const containerCss = Styles.Hooks.useClassName(accountDashboardListContainerStyle);
  const sortContainerCss = Styles.Hooks.useClassName(accountDashboardListSortContainerStyle);
  const footerCss = Styles.Hooks.useClassName(accountDashboardListFooterStyle);
  const items: number[] = new Array(50).fill(1);

  return (
    <div className={containerCss}>
      <div className={sortContainerCss}>
        <PlaceholderLoading shape="rect" height={16} width={50}/>
      </div>
      <div>
        {items.map((i, k) => <ItemPlaceHolder key={k}/>)}
      </div>
      <div className={footerCss}>
        <PlaceholderLoading shape="rect" height={16} width={40}/>
        <PlaceholderLoading shape="rect" height={16} width={16}/>
      </div>
    </div>
  );
};

export default AccountDashboardLoading;
