import {Account, AccountModel} from "../../../../../models/Account";
import {isNil} from "lodash";
import {DTGraphTypes} from "@dashthis/common";

export const formatAccountSearchResponse = (items: DTGraphTypes.Account[] | undefined): AccountModel[] => {
  let accounts: AccountModel[] = [];

  if (!isNil(items)) {
    accounts = items.map((a) => Account(a));
  }

  return accounts;
};

