import {accountManagersQuery} from "../queries/accountManager/accountManagers.query";
import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {AccountManager, AccountManagerModel} from "../models/AccountManager";
import {useMemo} from "react";

type ListListAccountManagersMatcher<R> = {
  onAccountManagersListed: (accountManagers: AccountManagerModel[]) => R,
  onAccountManagersListedError: (e: Client.Errors.ApplicationServerError) => R,
  onAccountManagersListing: () => R,
  onAccountManagersHold: () => R
}
type ListAccountManagers = {
  loading: boolean,
  error: Client.Errors.ApplicationServerError,
  accountManagers: AccountManagerModel[],
  matcher: <R>(matcher: ListListAccountManagersMatcher<R>) => R
}

const matchResponse = <R>(data: AccountManagerModel[], error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, loading: boolean, matcher: ListListAccountManagersMatcher<R>) => {
  if (error != null) {
    return matcher.onAccountManagersListedError(error);
  } else if (data != null && !loading) {
    return matcher.onAccountManagersListed(data);
  } else if (loading) {
    return matcher.onAccountManagersListing();
  }

  return matcher.onAccountManagersHold();
};

type Response = {
  accountManagers: DTGraphTypes.AccountManager[]
};

export const useListAccountManagers = (): ListAccountManagers => {
  const [response, error, loading] = Client.Hooks.useApolloQuery<{}, Response>(accountManagersQuery, {});
  const accountManagers = useMemo(() => loading || error != null ? [] : response.accountManagers.map((a) => AccountManager(a)), [response, error, loading]);

  return useMemo(() => ({
    loading,
    error,
    accountManagers,
    matcher: (matcher) => matchResponse(accountManagers, error, loading, matcher)
  }), [response, error, loading]);

};