import gql from "graphql-tag";
import {AccountSearchParts} from "../fragments/account/accountSearchParts";

export const searchAccountQuery = gql`
    query($query:String!,$limit:Int,$page:Int){
        accounts: searchAccounts(limit: $limit, page: $page, query: $query){
            count
            pages
            page
            items {
                ...AccountSearchParts

            }
        }
    }
    ${AccountSearchParts}
`;