import {AppSectionEnum} from "../app/enums/AppSectionEnum";
import {Enums as CommonEnums} from "@dashthis/common";
import {Enums} from "@dashthis/studio-common";
import {inDeveloppementEnv} from "./inDevelopementEnv";
import {IEventService} from "../services/eventService/types";

export const enabledOsMenuItemBaseOnSection = (section: AppSectionEnum, eventService: IEventService, env: CommonEnums.EnvsEnum = CommonEnums.EnvsEnum.NotAvailable) => {
  switch (section) {
    case AppSectionEnum.AccountManager:
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OpenByUrl, true);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.EmulateSettings, true);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.RefreshCaches, true);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.QuickOpen, true);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.Favorites, true);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OperationsRunAccountManagement, inDeveloppementEnv(env));
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OperationsRunEmailDispatch, inDeveloppementEnv(env));
      break;
    case AppSectionEnum.ConnectTo:
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OpenByUrl, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.EmulateSettings, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.RefreshCaches, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.QuickOpen, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.Favorites, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OperationsRunAccountManagement, false);
      eventService.send(Enums.IPCChannelEnum.EnabledDisabledMenu, Enums.MenuIdEnums.OperationsRunEmailDispatch, false);
      break;
  }
};