import {DTGraphTypes, Models} from "@dashthis/common";
import formatMessage from "format-message";
import dayjs from "dayjs";

interface IRecurrentPayment extends DTGraphTypes.RecurrentPayment {
  frequency: string;
  dateFormatted: (col: "lastPaymentDate" | "nextPaymentDate") => string;
}

export type RecurrentPaymentModel = Models.Types.Model<IRecurrentPayment>;

export const RecurrentPayment: Models.Types.ModelCtr<DTGraphTypes.RecurrentPayment, IRecurrentPayment> = (data) => ({
  ...data,
  get frequency() {
    return data.paymentFrequency === 1 ? formatMessage("Monthly") : formatMessage("Yearly");
  },
  dateFormatted(col) {
    if (data[col] == null) {
      return formatMessage("N/A");
    }

    const dateStr = dayjs(data[col]);

    return dateStr.calendar(undefined, {
      sameDay: "[Today]",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY"
    });
  }
});