import React, {Fragment, InputHTMLAttributes} from "react";
import {AccountManagerModel} from "../../models/AccountManager";
import {Hooks, Icon, Stack, Styles} from "@dashthis/ui";
import {accountManagerNamePickerStyle, accountManagerPickerImageContainerStyle, accountManagerPickerMenuIconStyle, accountManagerPickerStyle} from "./styles/accountManagerPicker.style";
import AccountManagerPopover from "./AccountManagerPopover";

interface IProps extends Omit<InputHTMLAttributes<HTMLDivElement>, "children"> {
  accountManager?: AccountManagerModel;
  accountManagerType: string;
  onAccountManagerSelect: (accountManager: AccountManagerModel) => void;
}

export const AccountManagerPicker = (props: IProps) => {
  const {accountManager, accountManagerType, value: valueProp, defaultValue, onChange, ...rest} = props;
  const {value, setValueIfUncontrolled} = Hooks.useControlled({
    controlled: valueProp,
    default: defaultValue
  });
  const [accountManagerSelected, setAccountManagerSelected] = React.useState<AccountManagerModel | undefined>(accountManager);
  const nameCss = Styles.Hooks.useClassName(accountManagerNamePickerStyle);
  const css = Styles.Hooks.useClassName(accountManagerPickerStyle);
  const imageCss = Styles.Hooks.useClassName(accountManagerPickerImageContainerStyle);
  const pickerMenuCss = Styles.Hooks.useClassName(accountManagerPickerMenuIconStyle);
  const inputRef = React.useRef<HTMLInputElement>(null);

  return (
    <Fragment>
      <input ref={inputRef} type="hidden" value={value} defaultValue={defaultValue} {...rest}/>
      <AccountManagerPopover onAccountManagerSelect={(e) => {
        const ev = new CustomEvent("change", {bubbles: true});

        setValueIfUncontrolled(e.id!);
        setAccountManagerSelected(e);
        inputRef.current!.value = e.id!;
        Object.defineProperty(ev, "target", {writable: false, value: inputRef.current});
        Object.defineProperty(ev, "currentTarget", {writable: false, value: inputRef.current});
        onChange?.(ev as any);
      }} accountManager={accountManagerSelected}>
        <Stack.VStack className={css} as="div" justifyItems={Stack.Enums.JustifyItemsEnum.Center} alignItems={Stack.Enums.AlignItemsEnum.Center}>
          <Stack.StackItem className={imageCss} as="div" itemSize="auto">
            <img alt="Account Manager" width={56} src={accountManagerSelected?.imageUrl}/>
            <div className={pickerMenuCss}>
              <Icon.Icons.ArrowDownIcon/>
            </div>
          </Stack.StackItem>
          <Stack.StackItem as="div" className={nameCss}>
            <span>{accountManagerSelected?.fullName}</span>
            <span>{accountManagerType}</span>
          </Stack.StackItem>
        </Stack.VStack>
      </AccountManagerPopover>
    </Fragment>
  );
};

export default AccountManagerPicker;
