import React, {HTMLAttributes, ReactNode} from "react";
import {Styles} from "@dashthis/ui";
import {sectionHeaderStyle} from "./styles/sectionHeader.styles";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Component children.
   */
  children?: ReactNode;
}

export const SectionHeader = (props: IProps) => {
  const {children, ...rest} = props;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, sectionHeaderStyle);

  return (
    <div {...rest} className={css}>{children}</div>
  );
};


export default SectionHeader;
