import React from "react";
import {RouteComponentProps} from "@reach/router";
import {Sheet, Styles} from "@dashthis/ui";
import {connectStudioLogoToStyle, connectToStyle} from "./styles/connectTo.style";
import {StudioLogoIcon} from "../../components/Icon/Icons";
import ConnectToDrawer from "./components/ConnectToDrawer";
import {useActivateMenuItemOnWindowFocus} from "../hooks/useActivateMenuItemOnWindowFocus";
import {AppSectionEnum} from "../enums/AppSectionEnum";
import {useActivateMenuItemSection} from "../hooks/useActivateMenuItemSection";

interface IProps extends RouteComponentProps {
}

export const ConnectTo = (props: IProps) => {
  const css = Styles.Hooks.useClassName(connectToStyle);
  const logoCss = Styles.Hooks.useClassName(connectStudioLogoToStyle);

  useActivateMenuItemOnWindowFocus(AppSectionEnum.ConnectTo);
  useActivateMenuItemSection(AppSectionEnum.ConnectTo);

  return (
    <Sheet.Components.Container>
      <div className={css}>
        <StudioLogoIcon className={logoCss}/>
        <ConnectToDrawer/>
      </div>
    </Sheet.Components.Container>
  );
};

export default ConnectTo;
