import {Client, DTGraphTypes} from "@dashthis/common";
import {Account, AccountModel} from "../models/Account";
import {accountsQuery} from "../queries/account/accounts.query";
import {useCallback} from "react";

type Response = {
  accounts: {
    accounts: DTGraphTypes.Account[],
    count: number
    pages: number
    page: number
  }
};

export type UseFindAccountByShortDashboardId = (id: string) => Promise<AccountModel | null>;

export const useFindAccountByShortDashboardId = (): UseFindAccountByShortDashboardId => {
  const client = Client.Hooks.useClient();
  const search = useCallback((id: string): Promise<AccountModel | null> => {
    return client.query<Response, DTGraphTypes.QueryAccountsArgs>({
      query: accountsQuery,
      variables: {
        query: id,
        limit: 1,
        page: 0
      }
    }).then((response) => {
      const accounts = response.data!.accounts;

      return accounts.accounts.length > 0 ? Promise.resolve(Account(accounts.accounts[0])) : Promise.resolve(null);
    }).catch((e) => {
      return Promise.reject(e);
    });
  }, [client]);

  return search;
};