import React from "react";
import {Stack, Styles, HamburgerMenu} from "@dashthis/ui";
import {dashboardReportItemContainerStyle, dashboardReportItemDateStyle, dashboardReportItemLetterStyle, dashboardReportItemStyle, dashboardReportItemTitleContainerStyle, dashboardReportItemTitleStyle} from "./styles/dashboardReportItem.style";
import {DashboardModel} from "../../../../../../models/Dashboard";
import {SourceModel} from "../../../../../../models/Source";
import DashboardReportSourceItem from "./DashboardReportSourceItem";
import {AuthorizationModel} from "../../../../../../models/Authorization";
import DashboardReportAuthorizationItem from "./DashboardReportAuthorizationItem";
import DashboardReportMenuAction from "./DashboardReportMenuAction";

interface IProps {
  dashboard: DashboardModel;
  sources: SourceModel[];
  authorizations: AuthorizationModel[];
}

export const DashboardReportItem = (props: IProps) => {
  const {dashboard, sources, authorizations} = props;
  const css = Styles.Hooks.useClassName(dashboardReportItemStyle);
  const containerCss = Styles.Hooks.useClassName(dashboardReportItemContainerStyle);
  const titleContainerCss = Styles.Hooks.useClassName(dashboardReportItemTitleContainerStyle);
  const titleCss = Styles.Hooks.useClassName(dashboardReportItemTitleStyle);
  const dateCss = Styles.Hooks.useClassName(dashboardReportItemDateStyle);
  const letterCss = Styles.Hooks.useClassName(dashboardReportItemLetterStyle, {
    color: dashboard.DashboardType!.color
  });

  return (
    <Stack.VStack className={containerCss} gap={5}>
      <Stack.HStack alignItems={Stack.Enums.AlignItemsEnum.Center} gap={5} as="div" className={css}>
        <Stack.StackItem itemSize="auto" as="span" className={letterCss}>{dashboard.DashboardType!.dashboardTypeLetter}</Stack.StackItem>
        <Stack.StackItem itemSize="1fr" as="div" className={titleContainerCss}>
          <span className={titleCss}>{dashboard.title}</span>
          <span className={dateCss}>{dashboard.lastAccessed}</span>
        </Stack.StackItem>
        <Stack.StackItem>
          <HamburgerMenu.HamburgerMenu menu={({hideMenu}) => <DashboardReportMenuAction hideMenu={hideMenu} dashboard={dashboard}/>}/>
        </Stack.StackItem>
      </Stack.HStack>
      {sources.map((s) => <Stack.StackItem key={s.id} source={s} as={DashboardReportSourceItem}/>)}
      {authorizations.map((s) => <Stack.StackItem key={s.id} authorization={s} as={DashboardReportAuthorizationItem}/>)}
    </Stack.VStack>
  );
};

export default DashboardReportItem;
