import React, {HTMLAttributes, ReactNode} from "react";
import {Gravatar} from "../../../Accounts/List/Gravatar";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountItemCompanyContainerStyle, accountItemCompanyIconStyle, accountItemCompanyNameStyle, accountItemGravatarStyle, accountItemStyle, accountItemTitleStyle} from "./styles/accountItem.style";
import {Plan} from "./Plan";
import AccountManager from "../../../Accounts/List/AccountManager";
import {Icon} from "../../../../../../components";

interface IProps extends Omit<HTMLAttributes<HTMLDivElement>, "onDoubleClick"> {
  /**
   * Component children.
   */
  children?: ReactNode;
  /**
   * The account model.
   */
  account: AccountModel;
  /**
   * Callback to call when user double click on item
   */
  onDoubleClick?: (account: AccountModel, e: React.MouseEvent) => void;
}

export const AccountItem = (props: IProps) => {
  const {account, children, onDoubleClick, ...rest} = props;
  const handleDoubleClick = (e: React.MouseEvent) => {
    if (onDoubleClick !== undefined) {
      onDoubleClick(account, e);
      e.stopPropagation();
    }
  };
  const getCreatorEmail = (): string => {
    return account.Creator != null ? account.Creator!.email : formatMessage("N/D");
  };
  const css = Styles.Hooks.useClassName(accountItemStyle);
  const titleCss = Styles.Hooks.useClassName(accountItemTitleStyle);
  const companyContainerCss = Styles.Hooks.useClassName(accountItemCompanyContainerStyle);
  const companyIconCss = Styles.Hooks.useClassName(accountItemCompanyIconStyle);
  const companyNameCss = Styles.Hooks.useClassName(accountItemCompanyNameStyle);
  const gravatarCss = Styles.Hooks.useClassName(accountItemGravatarStyle);

  return (
    <div {...rest} >
      <div onDoubleClick={handleDoubleClick} className={css}>
        <Gravatar className={gravatarCss} user={account.Creator!}/>
        <div>
          <span className={titleCss}>{getCreatorEmail()}</span>
          <div className={companyContainerCss}>
            <Icon.Icon className={companyIconCss} icon={Icon.Enums.Icons.Company}/>
            <span className={companyNameCss}>{account.CompanyName}</span>
          </div>
        </div>
        <Plan account={account}/>
        <AccountManager account={account}/>
      </div>
      {children}
    </div>
  );
};


export default AccountItem;
