import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {v4 as uuid} from "uuid";

interface ICsvSource extends DTGraphTypes.CsvSource, Search.Interfaces.IMatchableQuery {
  uiId: string;
}

export type CsvSourceModel = Models.Types.Model<ICsvSource>;

export const CsvSource: Models.Types.ModelCtr<DTGraphTypes.CsvSource, ICsvSource> = (data) => ({
  ...data,
  uiId: uuid(),
  matchQuery(query) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.name);
    searchableStrings.add(data.id);
    searchableStrings.add(data.providerKey);

    return searchableStrings.matchQuery();
  }
});