import {Client, DTGraphTypes} from "@dashthis/common";
import {searchUsersQuery} from "../../../../../queries/search/searchUsers";
import {SearchUsersResponse} from "./types";
import {AccountModel} from "../../../../../models/Account";
import {formatAccountSearchResponse} from "./formatResponse";
import {cloneDeep, isNil} from "lodash";
import {useMemo} from "react";

type UseSearchUsers = {
  accounts: AccountModel[],
  loading: boolean,
  error: Client.Errors.ApplicationServerError,
  count: number
}

const groupByAccount = (response: SearchUsersResponse): DTGraphTypes.Account[] => {
  const accounts: Map<string, DTGraphTypes.Account> = new Map();

  if (isNil(response.users.items)) {
    return Array.from(accounts.values());
  }

  response.users.items.forEach((u) => {
    if (u.account != null) {
      let account = cloneDeep(u.account!);

      if (accounts.has(account.id!)) {
        account = accounts.get(account.id!)!;
      }

      if (isNil(account.users)) {
        account.users = [];
      }
      account.users.push(u);
      accounts.set(account.id!, account);
    }
  });

  return Array.from(accounts.values());
};

export const useSearchUsers = (query: string): UseSearchUsers => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QuerySearchUsersArgs, SearchUsersResponse>(searchUsersQuery, {
    variables: {
      query,
      limit: 5
    }
  });

  return useMemo<UseSearchUsers>(() => ({
    accounts: loading || error != null ? [] : formatAccountSearchResponse(groupByAccount(data)),
    count: loading || error != null ? 0 : data.users.count,
    error,
    loading
  }), [data, error, loading]);

};

export default useSearchUsers;