import {Form, Styles, Window} from "@dashthis/ui";
import {Button, Input, Label} from "../../../../../../components";
import formatMessage from "format-message";
import {Formik, FormikHelpers, FormikProps} from "formik";
import React, {Fragment, useMemo} from "react";
import {Types} from "@dashthis/common";
import {EmulateSettingSchema} from "../schema/emulateSettingSchema";
import {useAppSettingsServiceContext} from "../../../../../../services/hooks/useAppSettingServiceContext";
import {diff} from "deep-diff";
import cleanDeep from "clean-deep";
import {emulateSettingDialogContentStyle} from "../styles/emulateSettingDialog.style";

interface IProps {
  /**
   * Callback to call when when to close dialog.
   */
  close: () => void;
}

type EmulateSettingsValues = {
  email: string,
  password: string
};

const windowSize: Types.Geometry.Size = {
  width: 500,
  height: 0
};

const cleanOption = {
  emptyStrings: false
};

const canSubmit = (initialValues: EmulateSettingsValues, changeValues: EmulateSettingsValues, isValid: boolean): boolean => {
  const changes = diff(initialValues, cleanDeep(changeValues, cleanOption));

  return !!changes && isValid;
};

export const EmulateSettingsWindow = (props: IProps) => {
  const {close} = props;
  const appSettingService = useAppSettingsServiceContext();
  const handleSubmit = (values: EmulateSettingsValues, actions: FormikHelpers<EmulateSettingsValues>) => {
    appSettingService.setEmulateSettings(values);
    close();
  };
  const handleCancelClick = () => {
    close();
  };
  const handleClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => () => {
    submit();
  };
  const initialValues = useMemo(() => appSettingService.getEmulateSettings(), [appSettingService]);
  const contentCss = Styles.Hooks.useClassName(emulateSettingDialogContentStyle);

  return (
    <Window.Window
      title={formatMessage("Emulate Settings")}
      onClose={close}
      size={windowSize}
    >
      <Formik
        validationSchema={EmulateSettingSchema}
        onSubmit={handleSubmit}
        validateOnMount
        initialValues={initialValues}
      >
        {(formikProps: FormikProps<EmulateSettingsValues>) => {
          return (
            <Fragment>
              <Window.Content className={contentCss}>
                <Form.Item>
                  <p>{formatMessage("Enter the email and password you want to use for the auto login when you emulate an account.")}</p>
                </Form.Item>
                <Form.Item>
                  <p>{formatMessage("The saved information will be used every time you emulate an account.")}</p>
                </Form.Item>
                <Form.Item>
                  <Label.Label>{formatMessage("Email")}: </Label.Label>
                  <Input.Input
                    autoFocus
                    value={formikProps.values.email}
                    name="email"
                    onChange={formikProps.handleChange}
                  />
                </Form.Item>
                <Form.Item>
                  <Label.Label>{formatMessage("Password")}: </Label.Label>
                  <Input.Input
                    value={formikProps.values.password}
                    type="password"
                    name="password"
                    onChange={formikProps.handleChange}
                  />
                </Form.Item>
              </Window.Content>
              <Window.Footer>
                <Button.Button onClick={handleCancelClick}>{formatMessage("Cancel")}</Button.Button>
                <Button.Button
                  type="submit"
                  disabled={!canSubmit(initialValues, formikProps.values, formikProps.isValid)}
                  onClick={handleClick(formikProps.handleSubmit)}
                  basic={false}>{formatMessage("Save")}</Button.Button>
              </Window.Footer>
            </Fragment>
          );
        }}
      </Formik>
    </Window.Window>
  );
};


export default EmulateSettingsWindow;