import {DTGraphTypes, Enums} from "@dashthis/common";
import {useCallback, useMemo, useState} from "react";
import {meQuery} from "../../../queries/me.query";
import {createClient} from "../../../client";

export const useValidConnectionForEnv = (env: Enums.EnvsEnum): [boolean, () => Promise<boolean>] => {
  const [processing, setProcessing] = useState(false);
  const client = useMemo(() => createClient(env), [env]);
  const checkConnection = useCallback(async (): Promise<boolean> => {
    setProcessing(true);

    try {
      const response = await client.query<DTGraphTypes.User>({
        query: meQuery,
        fetchPolicy: "no-cache"
      });

      setProcessing(false);

      return response != null && response.data != null;
    } catch (e) {
      setProcessing(false);

      return false;
    }

  }, [client]);

  return [processing, checkConnection];
};