import React, {ReactNode} from "react";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowSubHeaderStyle} from "./styles/fileTemplatesViewEditWindowSubHeader.style";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}


export const ViewEditFileTemplateWindowSubHeader = (props: IProps) => {
  const {children} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowSubHeaderStyle);

  return (
    <div className={css}>
      {children}
    </div>
  );
};


export default ViewEditFileTemplateWindowSubHeader;
