import React, {Fragment} from "react";
import {Styles} from "@dashthis/ui";
import LogoStudio from "../../../medias/svg/studio-logo.inline.svg";
import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../states/hooks";
import SearchBar from "./SearchBar";
import Taskbar from "./Taskbar/containers/Taskbar";
import SwitchableView from "./SwitchableView";
import {useOpenByUrl} from "../hooks/useOpenByUrl";
import {accountManagerMainBarStyle, accountManagerSearchBarStyle, accountManagerStyle, accountManagerSwitchStyle, accountManagerTaskBarStyle} from "../styles/accountManager.style";
import EmulateSettingsDialog from "./Dialogs/EmulateSettings";
import {useOnRefreshCaches} from "../hooks/useOnRefreshCaches";
import {useQuickOpen} from "../hooks/useQuickOpen";
import {useFavoriteMenu} from "../hooks/useFavoriteMenu";
import {useRunAccountManagementTask} from "../hooks/useRunAccountManagementTask";
import {ErrorBoundary} from "../../ErrorBoundary";
import {useRunEmailDispatchTask} from "../hooks/useRunEmailDispatchTask";

interface IProps {
}

export const AccountsManager = (props: IProps) => {
  const taskBarSelected = useAccountManagerStateSelector("taskBarSelected");
  const {setSearchQuery, addSearchToHistory, openAccounts, openDashboard, openUser, openFileTemplate} = useAccountManagerStateActions();
  const css = Styles.Hooks.useClassName(accountManagerStyle);
  const mainBarCss = Styles.Hooks.useClassName(accountManagerMainBarStyle);
  const taskBarCss = Styles.Hooks.useClassName(accountManagerTaskBarStyle);
  const switchCss = Styles.Hooks.useClassName(accountManagerSwitchStyle);
  const searchBarCss = Styles.Hooks.useClassName(accountManagerSearchBarStyle);

  useOpenByUrl();
  useQuickOpen();
  useOnRefreshCaches();
  useFavoriteMenu();
  useRunAccountManagementTask();
  useRunEmailDispatchTask();

  return (
    <Fragment>
      <div className={css}>
        <div className={searchBarCss}>
          <SearchBar
            openFileTemplate={openFileTemplate}
            openUser={openUser}
            openDashboard={openDashboard}
            openAccounts={openAccounts}
            addSearchToHistory={addSearchToHistory}
            setSearchQuery={setSearchQuery}
          />
        </div>
        <div className={mainBarCss}>
          <LogoStudio/>
        </div>
        <div className={taskBarCss}>
          <Taskbar/>
        </div>
        <div className={switchCss}>
          <ErrorBoundary>
            <SwitchableView taskBarSelectedItem={taskBarSelected}/>
          </ErrorBoundary>
        </div>
      </div>
      <EmulateSettingsDialog/>
    </Fragment>
  );
};


export default AccountsManager;