import {DocumentNode} from "graphql";
import gql from "graphql-tag";

export const accountDashboardsQuery: DocumentNode = gql`
    query($id:ID!, $showDeleted:Boolean){
        account(id:$id){
            id
            dashboards(showDeleted: $showDeleted) {
                id
                title
                shortId
                creationDate
                isDeleted
                dateDeleted
                dateLastAccessed
                customization {
                    ... on NoCustomization {
                        type
                    }
                    ... on CustomThemeCustomization {
                        id
                        name
                    }
                    ... on ColorThemeCustomization {
                        cssFileName
                    }
                    ... on WhiteLabelCustomization {
                        cssFileName
                    }
                }
                type {
                    id
                    name
                }
            }
        }
    }
`;