import {AccountFilter, AccountFilterStorage} from "./types";
import {v4 as uuid} from "uuid";
import {DTGraphTypes} from "@dashthis/common";

export const accountFilterService = (storage: AccountFilterStorage) => ({
  addOrUpdate(filter: AccountFilter): void {
    const f = this.get(filter.id);

    if (f == null) {
      this.add(filter);
    } else {
      this.update(filter);
    }
  },

  add(filter: AccountFilter): void {
    const filters = this.getAll();

    filters.push({
      ...filter
    });

    storage.set("accountFilter", filters);
  },
  clear(): void {
    storage.set("accountFilter", []);
  },
  get(id: string): AccountFilter | null {
    const filters = this.getAll();
    const f = filters.find((filter) => filter.id === id);

    if (f) {
      return f;
    }

    return null;
  },
  getAll(): AccountFilter[] {
    const filters = storage.get("accountFilter", []);

    if (filters == null) {
      const defaultFilter: AccountFilter[] = [{
        id: uuid(),
        name: "Active accounts",
        status: DTGraphTypes.AccountStatusGraphQl.Active
      }];

      storage.set("accountFilter", defaultFilter);

      return defaultFilter;
    }

    return filters as [AccountFilter];
  },
  remove(id: string): void {
    const filters = this.getAll();

    const filtersWithRemoved = filters.filter((f) => f.id !== id);

    storage.set("accountFilter", filtersWithRemoved);
  },
  update(filter: AccountFilter): void {
    const filters = this.getAll();

    const indexFilter = filters.findIndex((f) => f.id === filter.id);

    if (indexFilter !== -1) {
      filters.splice(indexFilter, 1, filter);
    }

    storage.set("accountFilter", filters);
  }
});