import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardWidgetsWidgetItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item",
  display: "grid",
  gridTemplateColumns: "auto 1fr auto",
  padding: `${utilities.space("t")} ${utilities.space("s")}`,
  alignItems: "center",
  gap: utilities.space("s"),
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  userSelect: "none",
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountDashboardWidgetsWidgetItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-selected",
  background: utilities.colors("chambray").alpha(.4).string()
});

export const accountDashboardWidgetsWidgetItemNotSelectableStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-not-selectable",
  pointerEvents: "none"
});

export const accountDashboardWidgetsWidgetItemTitleContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-container-title",
  ...utilities.ellipsis()
});

export const accountDashboardWidgetsWidgetItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-title",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular"
  })
});

export const accountDashboardWidgetsWidgetItemFormatterStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-formatter",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "tiny",
    color: "scorpion"
  })
});

export const accountDashboardWidgetsWidgetItemIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-widget-item-icon",
  width: 22,
  height: 22
});
