import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import formatMessage from "format-message";
import {Stack, Styles} from "@dashthis/ui";
import AccountManagerPicker from "../../../../../../components/AccountManagerPicker/AccountManagerPicker";
import {Field} from "formik";
import {accountPropertiesAccountManagerStyle} from "./styles/accountPropertiesAccountManager.style";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountPropertiesAccountManager = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountPropertiesAccountManagerStyle);

  return (
    <Stack.HStack className={css} justifyItems={Stack.Enums.JustifyItemsEnum.Center}>
      <Stack.StackItem>
        <Field value={account.AccountManager?.id} name="accountManagerId" accountManagerType={formatMessage("Account manager")} accountManager={account.AccountManager} as={AccountManagerPicker}/>
      </Stack.StackItem>
      <Stack.StackItem>
        <Field value={account.LowTierManager?.id} name="lowTierManagerId" accountManagerType={formatMessage("Lower tire manager")} accountManager={account.LowTierManager} as={AccountManagerPicker}/>
      </Stack.StackItem>
      <Stack.StackItem>
        <Field value={account.OwnerManager?.id} name="saleManagerId" accountManagerType={formatMessage("Owner manager")} accountManager={account.OwnerManager} as={AccountManagerPicker}/>
      </Stack.StackItem>
    </Stack.HStack>
  );
};

export default AccountPropertiesAccountManager;
