import React from "react";
import {TaskBarComponent} from "../components/Taskbar";
import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../../../states/hooks";

interface ITaskBarProps {
}

export const Taskbar = (props: ITaskBarProps) => {
  const accountFilters = useAccountManagerStateSelector("accountFilters");
  const taskBarSelected = useAccountManagerStateSelector("taskBarSelected");
  const searchHistories = useAccountManagerStateSelector("searchHistories");
  const searchQuery = useAccountManagerStateSelector("searchQuery");
  const openedAccounts = useAccountManagerStateSelector("openedAccounts");
  const {setTaskBarSelected, clearSearchHistory, deleteSearchHistory, setSearchQuery, closeAccounts} = useAccountManagerStateActions();

  return (
    <TaskBarComponent
      taskBarSelected={taskBarSelected}
      searchQuery={searchQuery}
      accountFilters={accountFilters}
      searchHistories={searchHistories}
      deleteSearchHistory={deleteSearchHistory}
      setSearchQuery={setSearchQuery}
      closeAccounts={closeAccounts}
      openedAccounts={openedAccounts}
      setTaskBarSelected={setTaskBarSelected}
      clearSearchHistory={clearSearchHistory}
      {...props}
    />
  );
};


export default Taskbar;
