import {StudioCSS} from "../../../../../../styles/types";

export const searchBarBodyStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-body",
  display: "flex",
  flexDirection: "column",
  top: "43px",
  left: "80px",
  width: "calc(100vw - 80px)",
  ...utilities.boxShadow({
    offsetX: 0,
    offsetY: 10,
    blurRadius: 10
  }),
  background: utilities.colors("white").string(),
  zIndex: 100,
  position: "absolute",
  borderTop: `${utilities.colors("geyser").string()} solid 1px`,
  maxHeight: "calc(100vh - 30%)"
});

export const searchBarBodyOverlayStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-body-overlay",
  zIndex: 99,
  position: "fixed",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  backgroundColor: utilities.colors("black").alpha(.5).string()
});

export const searchBarBodyNoResultStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-body-no-result",
  padding: utilities.space("n"),
  ...utilities.fontStyle({
    size: "small"
  }),
  opacity: .8
});

export const searchBarBodyNoResultTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-body-no-result-title",
  ...utilities.fontStyle({
    weight: "b"
  })
});

export const searchBarBodyResultStyle: StudioCSS = (theme, utilities) => ({
  label: "search-bar-body-result",
  flex: "1 1 auto",
  overflow: "auto"
});
