import {Styles} from "@dashthis/ui";
import {Button} from "../../../../../../components";
import {accountFeatureItemDescriptionStyle, accountFeatureItemEvenStyle, accountFeatureItemOddStyle, accountFeatureItemStyle, accountFeatureItemTitleStyle, accountFeatureItemToggleStyle} from "./styles/accountFeatureStyle";
import {useUpdateAccountFeatureFlag} from "../../../../../../hooks/useUpdateAccountFeatureFlag";
import {AccountModel} from "../../../../../../models/Account";
import {FeaturesModel} from "../../../../../../models/Features";
import React, {HTMLAttributes} from "react";
import {Conditional} from "@dashthis/common";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The account model.
   */
  account: AccountModel,
  /**
   * The feature model.
   */
  feature: FeaturesModel,
  /**
   * Indicate if row are odd and if true
   * draw white background
   */
  isOdd: boolean,
}

export const AccountFeatureItem = (props: IProps) => {
  const {account, feature, isOdd, ...rest} = props;
  const description = `Description for feature flag ${feature.id}`;
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props,
    accountFeatureItemStyle,
    Conditional.is(isOdd, accountFeatureItemOddStyle),
    Conditional.isNot(isOdd, accountFeatureItemEvenStyle)
  );
  const titleCss = Styles.Hooks.useClassName(accountFeatureItemTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(accountFeatureItemDescriptionStyle);
  const toggleCss = Styles.Hooks.useClassName(accountFeatureItemToggleStyle);
  const {activateFeatureFlag, processing, enabled} = useUpdateAccountFeatureFlag(account, feature.id!, feature.forcedValue);

  return (
    <div {...rest} className={css}>
      <div>
        <div className={titleCss}>{feature.name}</div>
        <div className={descriptionCss}>{description}</div>
      </div>
      <Button.ToggleButton
        className={toggleCss}
        name={feature.id!}
        checked={enabled}
        controlled
        disabled={processing || !feature.isManageable}
        onToggle={(e) => activateFeatureFlag((e.target as HTMLInputElement).checked)}
      />
    </div>
  );
};


export default AccountFeatureItem;
