import React from "react";
import {Line} from "react-chartjs-2";
import dayjs from "dayjs";
import {IStudioTheme} from "../../../../../../styles/studioTheme";
import {Styles} from "@dashthis/ui";
import {healthGraphStyle, healthGraphTitleStyle} from "../Dashboards/Health/styles/healthGraph.style";
import formatMessage from "format-message";
import {IntegrationsUsageModel} from "../../../../../../models/IntegrationsUsage";

interface IProps {
  /**
   * Array contains usage stats.
   */
  stats: IntegrationsUsageModel[];
}

const formatData = (stats: IntegrationsUsageModel[]) => {
  const labels = stats.map((s) => dayjs(s.date).format("MMM D"));
  const integrationCounts = stats.map((s) => s.nbIntegrations);
  const authorizationErrorCounts = stats.map((s) => s.errorsAuth);
  const theme = Styles.Hooks.useTheme<IStudioTheme>();

  return {
    labels,
    datasets: [{
      label: formatMessage("Connected integrations"),
      fill: false,
      data: integrationCounts,
      precision: 0,
      borderColor: theme.colors.primary.rgb().string()
    }, {
      label: formatMessage("Authorizations in errors"),
      fill: false,
      data: authorizationErrorCounts,
      borderColor: theme.colors.regentStBlue.rgb().string(),
      precision: 0
    }]
  };
};
const graphOptions = {
  maintainAspectRatio: true,
  scales: {
    xAxes: [{
      display: true,
      ticks: {
        callback: (dataLabel: string, index: number) => {
          return index % 2 === 0 ? dataLabel : "";
        }
      }
    }],
    yAxes: [{
      ticks: {
        stepSize: 2
      }
    }]
  }
};

export const IntegrationsUsage = React.memo<IProps>((props) => {
  const {stats} = props;
  const css = Styles.Hooks.useClassName(healthGraphStyle);
  const titleCss = Styles.Hooks.useClassName(healthGraphTitleStyle);

  return (
    <div className={css}>
      <span className={titleCss}>{formatMessage("Integrations and authorizations usage")}</span>
      <Line
        height={100}
        data={formatData(stats)}
        options={graphOptions}
      />
    </div>
  );
});


export default IntegrationsUsage;
