import React, {useMemo} from "react";
import {Styles} from "@dashthis/ui";
import {accountHeaderToolsStyle} from "./styles/accountHeaderTools.style";
import {AccountModel} from "../../../../../../models/Account";
import AccountHeaderFavoritesButton from "./AccountHeaderFavoritesButton";
import AccountHeaderHubSpotButton from "./AccountHeaderHubSpotButton";
import AccountHeaderEmulateButton from "./AccountHeaderEmulateButton";
import AccountHeaderStripeButton from "./AccountHeaderStripeButton";
import {useGetAccountUsers} from "../../../../../../hooks/useGetAccountUsers";

interface IProps {
  /**
   * The account model
   */
  account: AccountModel;
}

export const AccountHeaderTools = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountHeaderToolsStyle);
  const [users] = useGetAccountUsers(account.id!);
  const hubSpotUri = useMemo(() => {
    const mainContact = users.find(u => u.isHubSpotMainContact && u.hubSpotUri != null);
    const anyContact = users.find(u => u.hubSpotUri != null);

    return (mainContact ?? anyContact)?.hubSpotUri ?? null;
  }, [users]);

  return (
    <div className={css}>
      <AccountHeaderFavoritesButton account={account}/>
      <AccountHeaderHubSpotButton hubSpotUri={hubSpotUri}/>
      <AccountHeaderStripeButton account={account}/>
      <AccountHeaderEmulateButton account={account}/>
    </div>
  );
};


export default AccountHeaderTools;
