import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const accountFileTemplatesQuery: DocumentNode = gql`
    query($id:ID!, $showDeleted:Boolean){
        account(id:$id){
            id
            csvTemplates(showDeleted: $showDeleted) {
                id
                isDeleted
                dateRangeSeparator
                footerLines
                headerLines
                name
                separator
                sources {
                    id
                    name
                    providerKey
                }
                files {
                    id
                    name
                    providerKey
                    dateLastApplied
                    dateUploaded
                }
            }
        }
    }
`;