import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {SourceError, SourceErrorModel} from "./SourceError";
import {Authorization, AuthorizationModel} from "./Authorization";
import {v4 as uuid} from "uuid";

export interface ISource extends DTGraphTypes.Source, Search.Interfaces.IMatchableQuery {
  SourceError: SourceErrorModel | undefined
  Authorization: AuthorizationModel | undefined,
  hasError: boolean,
  uiId: string
}

export type SourceModel = Models.Types.Model<Omit<ISource, "error" | "authorization">>;

export const Source: Models.Types.ModelCtr<DTGraphTypes.Source, ISource> = (data) => ({
  ...data,
  uiId: uuid(),
  get SourceError() {
    return Models.createModel<DTGraphTypes.SourceError, SourceErrorModel>(data.error, SourceError);
  },
  get Authorization() {
    return Models.createModel<DTGraphTypes.Authorization, AuthorizationModel>(data.authorization, Authorization);
  },
  get hasError() {
    return data.error != null;
  },
  matchQuery(query: string) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.name);
    searchableStrings.add(data.providerKey);
    searchableStrings.add(data.id);

    return searchableStrings.matchQuery();
  }
});