import {DTGraphTypes, Models, Search} from "@dashthis/common";

export interface IFeatures extends DTGraphTypes.Feature, Search.Interfaces.IMatchableQuery {
}

export type FeaturesModel = Models.Types.Model<IFeatures>;

export const Features: Models.Types.ModelCtr<DTGraphTypes.Feature, IFeatures> = (data) => ({
  ...data,
  matchQuery(query: string): boolean {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.name);
    searchableStrings.add(data.id);

    return searchableStrings.matchQuery();
  }
});