import {Client, DTGraphTypes} from "@dashthis/common";
import {CsvTemplate, CsvTemplateModel, EmptyCsvTemplate} from "../models/CsvTemplate";
import {accountFileTemplateQuery} from "../queries/account/accountFileTemplate.query";
import {useMemo} from "react";

type Response = {
  account: DTGraphTypes.Account
};
export const useGetFileTemplateDetail = (id: string, accountId: string): [CsvTemplateModel, boolean, Client.Errors.ApplicationServerError] => {
  const variables = {
    id,
    accountId
  };
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QueryAccountArgs, Response>(accountFileTemplateQuery, {
    variables
  });

  return useMemo(() => ([
    loading || error != null ? EmptyCsvTemplate : CsvTemplate(data.account.csvTemplate!),
    loading,
    error
  ]), [data, error, loading]);

};