import React from "react";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {searchBarBodyNoResultStyle, searchBarBodyNoResultTitleStyle} from "./styles/searchBarBody.style";

type Props = {};

export const NoResults = (props: Props) => {
  const noResultCss = Styles.Hooks.useClassName(searchBarBodyNoResultStyle);
  const noResultTitleCss = Styles.Hooks.useClassName(searchBarBodyNoResultTitleStyle);

  return (
    <div className={noResultCss}>
      <p className={noResultTitleCss}>{formatMessage("No results")}</p>
      <p>{formatMessage("Studio couldn't find any messages related to your search…")}</p>
    </div>
  );
};


export default NoResults;
