import {StudioCSS} from "../../../styles/types";

export const connectToDrawerItemsStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-items",
  display: "grid",
  gap: utilities.space("s"),
  gridTemplateColumns: "auto auto auto auto",
  justifyContent: "center",
  alignItems: "center"
});

export const connectToDrawerItemStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item",
  display: "grid",
  gridTemplateColumns: "auto",
  padding: utilities.space("s"),
  justifyItems: "center",
  svg: {
    marginBottom: utilities.space("s"),
    width: 56
  }
});

export const connectToDrawerItemContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-container",
  position: "relative",
  minHeight: "140px",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  borderRadius: "2px",
  minWidth: "160px",
  "&:hover:not([class*=connect-to-drawer-item-container-loading])": {
    backgroundColor: utilities.colors("chambray").string(),
    cursor: "pointer"
  }
});

export const connectToDrawerItemContainerSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-container-selected",
  backgroundColor: utilities.colors("chambray").string(),
  pointerEvents: "none"
});

export const connectToDrawerItemContainerLoadingStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-container-loading",
  pointerEvents: "none"
});

export const connectToDrawerItemContainerDisabledStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-container-disabled",
  pointerEvents: "none",
  opacity: ".5"
});

export const connectToDrawerItemIndicatorStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-indicator",
  position: "absolute",
  height: "12px",
  borderRadius: "12px",
  width: "12px",
  top: 12,
  right: 12
});

export const connectToDrawerItemIndicatorUpStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-indicator-up",
  backgroundColor: utilities.colors("oliveDrab").string()
});

export const connectToDrawerItemIndicatorDownStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-to-drawer-item-indicator-down",
  backgroundColor: utilities.colors("burntUmber").string()
});