import {Client, DTGraphTypes} from "@dashthis/common";
import {useMemo} from "react";
import {accountFileTemplatesQuery} from "../../../../../../../queries/account/accountFileTemplates.query";
import {CsvTemplate, CsvTemplateModel} from "../../../../../../../models/CsvTemplate";

type QueryArgs = {
  id: string,
  showDeleted?: boolean
}

type Response = {
  account: DTGraphTypes.Account
}

type UseListAccountFileTemplates = {
  loading: boolean,
  error?: Client.Errors.ApplicationServerError,
  fileTemplates: CsvTemplateModel[]
}
export const useListAccountFileTemplates = (id: string): UseListAccountFileTemplates => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountFileTemplatesQuery, {
    variables: {
      id
    }
  });

  return useMemo(() => {
    return {
      loading,
      error,
      fileTemplates: loading || error != null ? [] : data.account.csvTemplates!.map((f) => CsvTemplate(f!))
    };
  }, [loading, error, data]);

};