import {StudioCSS} from "../../../styles/types";

export const buttonStyle: StudioCSS = (theme, utilities) => ({
  label: "studio-button",
  "&[class*=button]": {
    ...utilities.fontStyle({
      size: "tiny",
      weight: "b"
    })
  }
});

export const buttonDarkStyle: StudioCSS = (theme, utilities) => ({
  label: "studio-dark-button",
  "&[class*=button]": {
    backgroundColor: utilities.colors("scorpion").string(),
    borderColor: utilities.colors("scorpion").string()
  },
  "&[disabled]": {
    opacity: .5
  }
});
