import {taskBarAccountsQuery} from "../queries/taskBar/taskBarAccounts.query";
import {get} from "lodash";
import {Client} from "@dashthis/common";

type CountForAllAndNewSignupsAccount = {
  signupsCount: number,
  allCount: number
};
type CountForAllAndNewSignupsAccountResult = {
  all: {
    count: number
  }
  signups: {
    count: number
  }
};

export const useGetCountForAllAndNewSignupsAccount = (): [CountForAllAndNewSignupsAccount, boolean, Client.Errors.ApplicationServerError] => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<{}, CountForAllAndNewSignupsAccountResult>(taskBarAccountsQuery);
  const signupsCount = get(data, "signups.count", 0);
  const allCount = get(data, "all.count", 0);

  const result = {
    signupsCount,
    allCount
  };


  return [result, loading, error];
};