import React, {Fragment} from "react";
import {AccountNavigationBarItemsEnum} from "./enums/AccountNavigationBarItemsEnum";
import {Icon, NavigationBar} from "../../../../components";
import formatMessage from "format-message";
import SectionHeader from "./components/SectionHeader/SectionHeader";
import AccountSwitchSection from "./AccountSwitchSection";
import {Styles} from "@dashthis/ui";
import {accountBodyStyle} from "./styles/account.style";
import {AccountModel} from "../../../../models/Account";
import {useEnabledEmulateAccountMenu} from "../../hooks/useEnabledEmulateAccountMenu";
import {useAccountNavigation} from "./hooks/useAccountNavigation";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

const getSectionTitle = (section: AccountNavigationBarItemsEnum): string => {
  switch (section) {
    case AccountNavigationBarItemsEnum.Health:
      return formatMessage("Account Health");
    case AccountNavigationBarItemsEnum.Invoices:
      return formatMessage("Account Invoices");
    case AccountNavigationBarItemsEnum.Plan:
      return formatMessage("Account Plan");
    case AccountNavigationBarItemsEnum.Properties:
      return formatMessage("Account Properties");
    case AccountNavigationBarItemsEnum.RecurrentPayments:
      return formatMessage("Account Recurrent Payments");
    case AccountNavigationBarItemsEnum.Status:
      return formatMessage("Account Status History");
    case AccountNavigationBarItemsEnum.Users:
      return formatMessage("Account Users");
    case AccountNavigationBarItemsEnum.Dashboards:
      return formatMessage("Account Dashboards");
    case AccountNavigationBarItemsEnum.Actions:
      return formatMessage("Account Actions");
    case AccountNavigationBarItemsEnum.FileTemplates:
      return formatMessage("Account File Templates");
    case AccountNavigationBarItemsEnum.Features:
      return formatMessage("Account Features");
    case AccountNavigationBarItemsEnum.DashboardReport:
      return formatMessage("Dashboards Report");
  }
};

export const AccountNavigation = (props: IProps) => {
  const {account} = props;
  const {setNavigationBarSection, navigationBarSection} = useAccountNavigation();
  const handleNavigationBarClick = (section: AccountNavigationBarItemsEnum) => () => {
    setNavigationBarSection(section);
  };
  const bodyCss = Styles.Hooks.useClassName(accountBodyStyle);

  useEnabledEmulateAccountMenu(account);

  return (
    <Fragment>
      <SectionHeader>{getSectionTitle(navigationBarSection)}</SectionHeader>
      <div className={bodyCss}>
        <NavigationBar.NavigationBar>
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Health")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Health)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Health}
            icon={Icon.Enums.Icons.NavigationHealth}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Dashboards")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Dashboards)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Dashboards}
            icon={Icon.Enums.Icons.NavigationDashboard}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Dashboards Report")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.DashboardReport)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.DashboardReport}
            icon={Icon.Enums.Icons.NavigationDashboardReport}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Properties")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Properties)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Properties}
            icon={Icon.Enums.Icons.NavigationProperties}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Plan")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Plan)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Plan}
            icon={Icon.Enums.Icons.NavigationPlan}
          />
          {
            account.Status.isActive || account.Status.isCanceled
              ? <NavigationBar.NavigationBarItem
                tooltips={formatMessage("Account Recurrent Payments")}
                onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.RecurrentPayments)}
                selected={navigationBarSection === AccountNavigationBarItemsEnum.RecurrentPayments}
                icon={Icon.Enums.Icons.NavigationRecurrentPayments}
              />
              : null
          }
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("File Templates")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.FileTemplates)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.FileTemplates}
            icon={Icon.Enums.Icons.NavigationCsv}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Invoices")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Invoices)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Invoices}
            icon={Icon.Enums.Icons.NavigationInvoices}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Users")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Users)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Users}
            icon={Icon.Enums.Icons.NavigationUsers}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Status History")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Status)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Status}
            icon={Icon.Enums.Icons.NavigationStatus}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Action")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Actions)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Actions}
            icon={Icon.Enums.Icons.NavigationAction}
          />
          <NavigationBar.NavigationBarItem
            tooltips={formatMessage("Account Features")}
            onClick={handleNavigationBarClick(AccountNavigationBarItemsEnum.Features)}
            selected={navigationBarSection === AccountNavigationBarItemsEnum.Features}
            icon={Icon.Enums.Icons.NavigationFeatures}
          />
        </NavigationBar.NavigationBar>
        <AccountSwitchSection account={account} section={navigationBarSection}/>
      </div>
    </Fragment>
  );
};

export default AccountNavigation;
