import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import React, {useCallback, useEffect} from "react";
import {Enums} from "@dashthis/studio-common";
import {Dialog, Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import * as Yup from "yup";
import {useAccountManagerStateActions} from "../../../states/hooks";
import {useFindAccountById} from "../../../hooks/useFindAccountById";

export const useQuickOpen = () => {
  const eventService = useEventServiceContext();
  const findBytId = useFindAccountById();
  const {openAccounts} = useAccountManagerStateActions();
  const quickOpen = useCallback(() => {
    Dialog.ApplicationDialogs.prompt({
      title: formatMessage("Quick Open"),
      message: formatMessage("Paste the account id in the field below to open account"),
      label: formatMessage("Account Id"),
      okText: formatMessage("Open"),
      schema: Yup.object().shape({
        value: Yup.string()
          .uuid()
          .required(formatMessage("This field is required."))
      }),
      okClick: async (value) => {
        const hideNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Opening account...")}</Notification.LoadingNotification>);

        try {
          const account = await findBytId(value);

          if (account != null) {
            openAccounts(new Set([account.id!]));
          } else {
            Services.toastNotificationService.display(<Notification.WarningNotification>{formatMessage("We have not found any account associated to this id.")}</Notification.WarningNotification>);
          }
          hideNotification();
        } catch (e) {
          Services.clientService.Error.displayError(e, formatMessage("Error on opening account"));
          hideNotification();
        }

      }
    });
  }, [openAccounts]);

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.QuickOpen, quickOpen);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.QuickOpen, quickOpen);
    };
  }, [eventService, quickOpen]);
};