import React from "react";
import formatMessage from "format-message";
import {AccountModel} from "../../../../../models/Account";
import {Styles} from "@dashthis/ui";
import {accountManagerGravatarStyle, accountManagerNameStyle, accountManagerNotAssignedStyle, accountManagerStatusStyle, accountManagerStyle} from "./styles/accountManager.style";

interface Props {
  /**
   * The account manager model.
   */
  account: AccountModel;
}

export const AccountManager = (props: Props) => {
  const {account} = props;
  const ownerManager = account.OwnerManager;
  const css = Styles.Hooks.useClassName(accountManagerStyle);
  const gravatarCss = Styles.Hooks.useClassName(accountManagerGravatarStyle);
  const nameCss = Styles.Hooks.useClassName(accountManagerNameStyle);
  const notAssignedCss = Styles.Hooks.useClassName(accountManagerNameStyle, accountManagerNotAssignedStyle);
  const statusCss = Styles.Hooks.useClassName(accountManagerStatusStyle);

  if (ownerManager == null) {
    return (<span className={notAssignedCss}>{formatMessage("No owner manager assigned.")}</span>);
  }

  return (
    <div className={css}>
      <img alt="gravatar" className={gravatarCss} src={ownerManager.avatarUrl()}/>
      <span className={nameCss}>{ownerManager.fullName}</span>
      <span className={statusCss}>{account.Status.toString()}</span>
    </div>
  );
};


export default AccountManager;
