import {Client, DTGraphTypes} from "@dashthis/common";
import {Dashboard, DashboardModel} from "../models/Dashboard";
import {accountDashboardQuery} from "../queries/account/accountDashboard.query";

type Response = {
  account: DTGraphTypes.Account
};

type QueryArgs = {
  id: string,
  dashboardId: string
};

export const useGetAccountDashboardDetails = (id: string, dashboardId: string): [DashboardModel, boolean, Client.Errors.ApplicationServerError] => {
  const variables = {
    id,
    dashboardId
  };
  const [data, error, loading] = Client.Hooks.useApolloQuery<QueryArgs, Response>(accountDashboardQuery, {
    variables
  });

  if (loading || error !== undefined || data.account.dashboard == null) {
    return [Dashboard({}), loading, error];
  }

  return [Dashboard(data.account.dashboard), loading, error];
};