import React, {Fragment} from "react";
import ViewEditFileTemplateWindowSubHeader from "./ViewEditFileTemplateWindowSubHeader";
import formatMessage from "format-message";
import ViewEditFileTemplateWindowText from "./ViewEditFileTemplateWindowText";
import {Styles} from "@dashthis/ui";
import {fileTemplatesViewEditWindowMetricSectionStyle} from "./styles/fileTemplatesViewEditWindow.style";
import ViewEditFileTemplateWindowHeader from "./ViewEditFileTemplateWindowHeader";
import {CsvTemplateModel} from "../../../../../../../../models/CsvTemplate";
import ViewEditFileTemplateWindowSelectDataType from "./ViewEditFileTemplateWindowSelectDataType";
import ViewEditFileTemplateWindowInput from "./ViewEditFileTemplateWindowInput";
import {Field} from "formik";
import {useGetCsvFieldPositionInInitialValue} from "../../hooks/useGetCsvFieldPositionInInitialValue";

interface IProps {
  /**
   * The csv template model.
   */
  csvTemplate: CsvTemplateModel;

}

export const ViewEditFileTemplateWindowMetricSection = (props: IProps) => {
  const {csvTemplate} = props;
  const getFieldPosition = useGetCsvFieldPositionInInitialValue();
  const metricSectionCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowMetricSectionStyle);
  const metricFields = csvTemplate.getMetricFields();

  return (
    <Fragment>
      <ViewEditFileTemplateWindowHeader>{formatMessage("Metrics")}</ViewEditFileTemplateWindowHeader>
      <div className={metricSectionCss}>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Name")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Format")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("Decimals")}</ViewEditFileTemplateWindowSubHeader>
        <ViewEditFileTemplateWindowSubHeader>{formatMessage("No Column")}</ViewEditFileTemplateWindowSubHeader>
        {metricFields.map((m, k) => (
          <Fragment key={k}>
            <ViewEditFileTemplateWindowText>{m.name}</ViewEditFileTemplateWindowText>
            <Field name={`dataFields[${getFieldPosition(m.id!)}].dataFormat`} as={ViewEditFileTemplateWindowSelectDataType}/>
            <Field name={`dataFields[${getFieldPosition(m.id!)}].decimals`} as={ViewEditFileTemplateWindowInput}/>
            <ViewEditFileTemplateWindowText>{m.columnIndex}</ViewEditFileTemplateWindowText>
          </Fragment>
        ))}
      </div>
    </Fragment>
  );
};


export default ViewEditFileTemplateWindowMetricSection;
