import {Styles} from "@dashthis/ui";

export const healthBoxStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "health-box",
  background: utilities.colors("primary").string(),
  color: utilities.colors("white").string(),
  borderRadius: 2,
  padding: `${utilities.space("n")} ${utilities.space("l")}`,
  minWidth: 125,
  height: 85,
  display: "flex",
  flexDirection: "column",
  alignItems: "flex-start",
  justifyContent: "center",
  "span:nth-child(1)": {
    display: "block",
    ...utilities.fontStyle({
      size: "massive",
      weight: "b"
    })
  },
  "span:nth-child(2)": {
    display: "block",
    ...utilities.fontStyle({
      size: "large",
      weight: "n"
    })
  }
});
