import {useSelector} from "react-redux";
import {IStudioStates} from "../reducers";
import {IAccountManagerState} from "../reducers/accountManager";

export const useAccountManagerStateSelector = <T extends keyof IAccountManagerState>(key: T): IAccountManagerState[T] =>
  useSelector<IStudioStates, IAccountManagerState[T]>(((state) => state.accountManager[key]));