import {StudioCSS} from "../../../styles/types";

export const connectFormContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-form-container",
  display: "grid",
  gridTemplateColumns: "auto",
  gridTemplateRows: "1fr auto",
  alignItems: "center",
  width: 415,
  background: utilities.colors("primary").string(),
  ...utilities.boxShadow({
    blurRadius: 11,
    spreadRadius: 6,
    color:utilities.colors("black").alpha(.1)
  })
});

export const connectFormStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-form",
  display: "grid",
  gap: utilities.space.normal,
  width: "100%",
  padding: utilities.space.extraLarge,
  gridTemplateColumns: "auto",
  gridTemplateRows: "auto auto",
  justifySelf: "center"
});

export const connectFormHeaderStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-form-header",
  p: {
    color: utilities.colors("white").toString(),
    "&:nth-of-type(1)": {
      ...utilities.fontStyle({
        weight: "m",
        size: "large"
      })
    },
    "&:nth-of-type(2)": {
      ...utilities.fontStyle({
        size: "small"
      })
    }
  }
});

export const connectFormButtonsStyle: StudioCSS = (theme, utilities) => ({
  label: "connect-form-buttons",
  backgroundColor: utilities.colors("mineShaft").string(),
  padding: utilities.space.normal,
  display: "grid",
  gridTemplateColumns: "1fr auto",
  justifyItems: "flex-end",
  gap: utilities.space("s")
});

