import {QueryProcessor, Styles} from "@dashthis/ui";
import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import {useGetAccountStatusHistory} from "../../../../../../hooks/useGetAccountStatusHistory";
import AccountStatusHistoryItem from "./AccountStatusHistoryItem";
import {accountStatusHistoryContainerStyle, accountStatusHistoryStyle} from "./styles/accountStatusHistory.style";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountStatusHistory = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountStatusHistoryStyle);
  const containerCss = Styles.Hooks.useClassName(accountStatusHistoryContainerStyle);
  const [statusHistory, loading, error] = useGetAccountStatusHistory(account.id!);

  return (
    <QueryProcessor.QueryProcessor loading={loading} error={error}>
      <div className={containerCss}>
        <div className={css}>
          {statusHistory.map((status, index) => (<AccountStatusHistoryItem last={index === 0} key={index} statusHistory={status} invert={index % 2 === 0}/>))}
        </div>
      </div>
    </QueryProcessor.QueryProcessor>
  );
};


export default AccountStatusHistory;
