import React, {ReactNode} from "react";
import {useSearchAccounts} from "../hooks/useSearchAccounts";
import {useSearchDashboards} from "../hooks/useSearchDashboards";
import {useSearchUsers} from "../hooks/useSearchUsers";
import {Client} from "@dashthis/common";
import {Accounts} from "./Accounts/Accounts";
import {Users} from "./Users/Users";
import {Dashboards} from "./Dashboards/Dashboards";
import {Body} from "./Body";
import NoResults from "./NoResults";
import {AccountModel} from "../../../../../models/Account";
import {OpenAccounts, OpenDashboard, OpenFileTemplate, OpenUser} from "../../../../../states/actions";
import {Styles} from "@dashthis/ui";
import {searchBarBodyResultStyle} from "./styles/searchBarBody.style";
import useSearchFileTemplates from "../hooks/useSearchFileTemplates";
import FileTemplates from "./FileTemplates/FileTemplates";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode,
  /**
   * the search query.
   */
  query: string,
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  openDashboard: OpenDashboard;
  openUser: OpenUser;
  openFileTemplate: OpenFileTemplate
}

const hasResult = (items: AccountModel[], loading: boolean, error: Client.Errors.ApplicationServerError): boolean => {
  return !loading && error === undefined && items.length > 0;
};
const stillLoading = (...states: boolean[]): boolean => {
  return states.some((v) => v);
};
const noResults = (...states: AccountModel[][]): boolean => {
  return states.every((v) => v !== undefined && v.length === 0);
};

export const SearchResult = React.memo<IProps>((props: IProps) => {
  const {query, openAccounts, openDashboard, openUser, openFileTemplate} = props;
  const searchBodyCss = Styles.Hooks.useClassName(searchBarBodyResultStyle);
  const accountsResult = useSearchAccounts(query);
  const dashboardsResult = useSearchDashboards(query);
  const userSearchResult = useSearchUsers(query);
  const fileTemplateResult = useSearchFileTemplates(query);

  return (
    <Body loading={stillLoading(accountsResult.loading, dashboardsResult.loading, userSearchResult.loading, fileTemplateResult.loading)} className={searchBodyCss}>
      {hasResult(accountsResult.accounts, accountsResult.loading, accountsResult.error)
        ? <Accounts total={accountsResult.count} count={accountsResult.accounts.length} openAccounts={openAccounts} accounts={accountsResult.accounts}/>
        : null
      }
      {hasResult(dashboardsResult.accounts, dashboardsResult.loading, dashboardsResult.error)
        ? <Dashboards openDashboard={openDashboard} total={dashboardsResult.count} count={dashboardsResult.accounts.length} openAccounts={openAccounts} accounts={dashboardsResult.accounts}/>
        : null
      }
      {hasResult(userSearchResult.accounts, userSearchResult.loading, userSearchResult.error)
        ? <Users openUser={openUser} total={userSearchResult.count} count={userSearchResult.accounts.length} openAccounts={openAccounts} accounts={userSearchResult.accounts}/>
        : null
      }
      {hasResult(fileTemplateResult.accounts, fileTemplateResult.loading, fileTemplateResult.error)
        ? <FileTemplates openFileTemplate={openFileTemplate} total={fileTemplateResult.count} count={fileTemplateResult.accounts.length} openAccounts={openAccounts} accounts={fileTemplateResult.accounts}/>
        : null
      }
      {!stillLoading(accountsResult.loading, dashboardsResult.loading, userSearchResult.loading, fileTemplateResult.loading) && noResults(accountsResult.accounts, dashboardsResult.accounts, userSearchResult.accounts, fileTemplateResult.accounts)
        ? <NoResults/>
        : null
      }
    </Body>
  );
});


export default SearchResult;
