import React, {ReactNode} from "react";
import {Button, Form, Input} from "../../../components";
import {Formik, FormikHelpers, FormikProps} from "formik";
import {LoginSchema} from "../schema/login";
import {Styles} from "@dashthis/ui";
import {Enums, Hooks} from "@dashthis/common";
import formatMessage from "format-message";
import keycode from "keycode";
import {connectFormButtonsStyle, connectFormContainerStyle, connectFormHeaderStyle, connectFormStyle} from "../styles/connectForm.style";
import {useLogin} from "../hooks/useLogin";
import {useRouterContext} from "../../../router";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
  /**
   * Callback to call when user click on cancel button or hit esc key.
   */
  onCancel: () => void;
  /**
   *
   */
  env: Enums.EnvsEnum;
}

export type LoginValue = {
  email: string;
  password: string;
};

const initialValues: LoginValue = {
  email: "",
  password: ""
};

export const ConnectForm = (props: IProps) => {
  const {history} = useRouterContext();
  const {onCancel, env} = props;
  const [login, processing] = useLogin(env);
  const handleKeyPress = (submit: (formEvent?: React.FormEvent<HTMLFormElement>) => void) => (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (keycode(e as any) === keycode.names[13]) {
      submit();
    }
  };
  const handleClick = (submit: (e?: React.FormEvent<HTMLFormElement>) => void) => (e: React.MouseEvent) => {
    submit();
  };
  const handleSubmit = async (values: LoginValue, actions: FormikHelpers<LoginValue>) => {
    await login(values.email, values.password);
    await history!.navigate(`/accountManager/${env}`);
  };
  const formCss = Styles.Hooks.useClassName(connectFormStyle);
  const formContainerCss = Styles.Hooks.useClassName(connectFormContainerStyle);
  const buttonsCss = Styles.Hooks.useClassName(connectFormButtonsStyle);
  const headerCss = Styles.Hooks.useClassName(connectFormHeaderStyle);

  Hooks.useEventListener<KeyboardEvent>("keydown", (e) => {
    if (e.key === "Escape") {
      onCancel();
    }
  });

  return (
    <Formik
      validationSchema={LoginSchema}
      onSubmit={handleSubmit}
      initialValues={initialValues}
      validateOnBlur={false}
    >
      {(formikProps: FormikProps<LoginValue>) => {
        return (
          <div onKeyPress={handleKeyPress(formikProps.handleSubmit)} className={formContainerCss}>
            <div className={formCss}>
              <div className={headerCss}>
                <p>{formatMessage("Please enter your email and password to continue.")}</p>
                <p>{formatMessage("For login on Studio, you need to have a DashThis Admin account")}</p>
              </div>
              <Form.DarkFormikError field="email">
                <Input.DarkInput
                  autoFocus
                  value={formikProps.values.email}
                  name="email"
                  onChange={formikProps.handleChange}
                  onBlur={formikProps.handleBlur}
                  placeholder={formatMessage("Email")}
                />
              </Form.DarkFormikError>
              <Form.DarkFormikError field="password">
                <Input.DarkInput
                  value={formikProps.values.password}
                  name="password"
                  onChange={formikProps.handleChange}
                  type="password"
                  onBlur={formikProps.handleBlur}
                  placeholder={formatMessage("Password")}
                />
              </Form.DarkFormikError>
            </div>
            <div className={buttonsCss}>
              <Button.DarkButton
                basic={false}
                disabled={processing}
                onClick={onCancel}
              >
                {formatMessage("Cancel")}
              </Button.DarkButton>
              <Button.DarkButton
                type="submit"
                disabled={!formikProps.isValid}
                basic={false}
                loading={processing}
                onClick={handleClick(formikProps.handleSubmit)}
              >
                {formatMessage("Connect")}
              </Button.DarkButton>
            </div>
          </div>
        );
      }}
    </Formik>
  );
};


export default ConnectForm;
