import {DTGraphTypes, Models} from "@dashthis/common";
import {CsvFile, CsvFileModel} from "./CsvFile";
import {CsvSource, CsvSourceModel} from "./CsvSource";
import {CsvDataField, CsvDataFieldModel} from "./CsvDataField";


interface ICsvTemplate extends DTGraphTypes.CsvTemplate {
  Files: Models.Types.Models<CsvFileModel>,
  Sources: Models.Types.Models<CsvSourceModel>,
  Fields: Models.Types.Models<CsvDataFieldModel>,
  getCustomerIdField: () => CsvDataFieldModel | undefined,
  getDateField: () => CsvDataFieldModel | undefined,
  getDateFieldIndex: () => number,
  getMetricFields: () => CsvDataFieldModel[],
  getDimensionFields: () => CsvDataFieldModel[],
}

export type CsvTemplateModel = Models.Types.Model<Omit<ICsvTemplate, "files" | "sources">>;

export const CsvTemplate: Models.Types.ModelCtr<DTGraphTypes.CsvTemplate, ICsvTemplate> = (data) => ({
  ...data,
  get Files() {
    return Models.createModels<DTGraphTypes.CsvFile, CsvFileModel>(data.files, CsvFile);
  },
  get Sources() {
    return Models.createModels<DTGraphTypes.CsvSource, CsvSourceModel>(data.sources, CsvSource);
  },
  get Fields() {
    return Models.createModels<DTGraphTypes.CsvDataField, CsvDataFieldModel>(data.fields, CsvDataField);
  },
  getCustomerIdField() {
    return this.Fields.find((f) => f.fieldType === "Header" && f.name === "Source");
  },
  getDateField() {
    return this.Fields.find((f) => f.fieldType === "Header" && f.name === "Date");
  },
  getDateFieldIndex() {
    return this.Fields.findIndex((f) => f.fieldType === "Header" && f.name === "Date");
  },
  getDimensionFields() {
    return this.Fields.filter((f) => f.dataType === "Dim");
  },
  getMetricFields() {
    return this.Fields.filter((f) => f.dataType === "Metric");
  }
});

export const EmptyCsvTemplate = CsvTemplate({
  dateRangeSeparator: "",
  encoding: "UTF-8",
  footerLines: 0,
  headerLines: 0,
  isDeleted: false,
  name: "",
  separator: ""
});