import React from "react";
import {useAccountManagerStateActions, useAccountManagerStateSelector} from "../../../../../states/hooks";
import formatMessage from "format-message";
import {Body} from "./Body";
import {Icon, Styles} from "@dashthis/ui";
import {searchBarSearchHistoryItemClearIconStyle, searchBarSearchHistoryItemIconStyle, searchBarSearchHistoryItemStyle, searchBarSearchHistoryNoItemsStyle, searchBarSearchHistoryStyle, searchBarSearchHistoryTitleStyle} from "./styles/searchBarSearchHistory.style";

type Props = {
  /**
   * Component children.
   */
  query: string,
  /**
   * Callback to call when history is clicked.
   */
  onHistoryClick: (history: string) => void
};

export const HistorySearch = React.memo<Props>((props: Props) => {
  const {query, onHistoryClick} = props;
  const searchHistories = useAccountManagerStateSelector("searchHistories");
  const {deleteSearchHistory} = useAccountManagerStateActions();
  const handleHistoryClick = (history: string) => (e: React.MouseEvent) => {
    onHistoryClick(history);
  };
  const handleClearHistoryClick = (history: string) => (e: React.MouseEvent) => {
    deleteSearchHistory(history);
    e.stopPropagation();
  };
  const filterHistories = (): string[] => {
    if (query !== "") {
      return searchHistories.filter((h) => h.toLowerCase().includes(query.toLowerCase())).slice(0, 10);
    }

    return searchHistories.slice(0, 10);
  };
  const bodyCss = Styles.Hooks.useClassName(searchBarSearchHistoryStyle);
  const bodyTitleCss = Styles.Hooks.useClassName(searchBarSearchHistoryTitleStyle);
  const noItemsCss = Styles.Hooks.useClassName(searchBarSearchHistoryNoItemsStyle);
  const itemCss = Styles.Hooks.useClassName(searchBarSearchHistoryItemStyle);
  const itemIconCss = Styles.Hooks.useClassName(searchBarSearchHistoryItemIconStyle);
  const itemClearIconCss = Styles.Hooks.useClassName(searchBarSearchHistoryItemClearIconStyle);

  return (
    <Body loading={false} className={bodyCss}>
      <p className={bodyTitleCss}>{formatMessage("Recent searches")}</p>
      {searchHistories.length === 0 ? <p className={noItemsCss}>{formatMessage("No recent search...")}</p> : null}
      {filterHistories().map((h) => (
        <div onClick={handleHistoryClick(h)} className={itemCss} key={h}>
          <Icon.Icon className={itemIconCss} icon={Icon.Enums.Icons.Magnifier}/>
          <span>{h}</span>
          <Icon.Icon onClick={handleClearHistoryClick(h)} className={itemClearIconCss} icon={Icon.Enums.Icons.Clear}/>
        </div>
      ))}
    </Body>
  );
});


export default HistorySearch;
