import React from "react";
import {Form, PropertyList, Styles} from "@dashthis/ui";
import formatMessage from "format-message";
import {Field, useFormikContext} from "formik";
import {IAccountInput} from "./AccountProperties";
import {propertyListContainerStyle, propertyListStyle} from "./styles/propertyList.style";

export const AccountPropertyList = () => {
  const {values} = useFormikContext<IAccountInput>();
  const canUsePoweredBy = (): boolean => {
    return values.customSettings?.customCSS == null || values.customSettings?.customCSS !== "";
  };
  const css = Styles.Hooks.useClassName(propertyListContainerStyle);
  const listCss = Styles.Hooks.useClassName(propertyListStyle);

  return (
    <div className={css}>
      <PropertyList.List className={listCss}>
        <PropertyList.Group>{formatMessage("White label")}</PropertyList.Group>
        <Field name="customSettings.customCSS" label={formatMessage("Skin")} as={PropertyList.ItemValue}/>
        <Field name="customSettings.poweredBy" label={formatMessage("Show power by")} disabled={canUsePoweredBy()} checked={values.customSettings?.poweredBy} checkboxLabel={formatMessage("Yes")} as={PropertyList.ItemCheckbox}/>
        <PropertyList.Group>{formatMessage("Dashboard")}</PropertyList.Group>
        <Form.ErrorFieldWrapper field="dashboardSettings.maxMonthImport">
          <Field name="dashboardSettings.maxMonthImport" label={formatMessage("Imported month")} as={PropertyList.ItemValue}/>
        </Form.ErrorFieldWrapper>
        <Form.ErrorFieldWrapper field="dashboardSettings.maxWidgets">
          <Field name="dashboardSettings.maxWidgets" label={formatMessage("Widget per dashboard")} as={PropertyList.ItemValue}/>
        </Form.ErrorFieldWrapper>
        <Form.ErrorFieldWrapper field="dashboardSettings.maxSources">
          <Field name="dashboardSettings.maxSources" label={formatMessage("Max number of sources")} as={PropertyList.ItemValue}/>
        </Form.ErrorFieldWrapper>
      </PropertyList.List>
    </div>
  );
};


export default AccountPropertyList;
