import {useAccountPersistedState} from "../../../hooks/useAccountPersistedState";
import {WidgetModel} from "../../../../../../../models/Widget";
import {useCallback} from "react";
import {SourceModel} from "../../../../../../../models/Source";
import {DashboardModel} from "../../../../../../../models/Dashboard";
import {AuthorizationModel} from "../../../../../../../models/Authorization";

export type MultipleSelectItemWidget = {
  type: "widget",
  id: string,
  widget: WidgetModel
}
export type MultipleSelectItemSource = {
  type: "source",
  id: string,
  source: SourceModel
}

export type MultipleSelectItemAuthorization = {
  type: "authorization",
  id: string,
  authorization: AuthorizationModel
}

export type MultipleSelectItems = (MultipleSelectItemWidget | MultipleSelectItemSource | MultipleSelectItemAuthorization)[];
export type MultipleSelectSelectItem = (item: MultipleSelectItemWidget | MultipleSelectItemSource | MultipleSelectItemAuthorization, keep: boolean) => void;
export type MultipleSelectIsItemAreSelected = (id: string) => boolean

export const useMultipleSelectItems = (dashboard: DashboardModel): {
  selectedItems: MultipleSelectItems,
  selectItem: MultipleSelectSelectItem,
  isItemAreSelected: MultipleSelectIsItemAreSelected
} => {
  const [selectedItems, setSelectedItems] = useAccountPersistedState<MultipleSelectItems>(`widgetListSelected${dashboard.id}`, []);
  const selectItem = useCallback((item: MultipleSelectItemWidget | MultipleSelectItemSource | MultipleSelectItemAuthorization, keep: boolean) => {
    if (keep) {
      if (selectedItems.some((w) => w.id === item.id)) {
        setSelectedItems(selectedItems.filter((w) => w.id !== item.id));
      } else {
        setSelectedItems([...selectedItems, item]);
      }
    } else {
      setSelectedItems([item]);
    }
  }, [selectedItems, setSelectedItems]);
  const isItemAreSelected = useCallback((id: string): boolean => {
    return selectedItems.some((w) => w.id === id);
  }, [selectedItems]);

  return {
    selectedItems,
    selectItem,
    isItemAreSelected
  };
};