import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const accountUsageQuery: DocumentNode = gql`
    query($id:ID!, $start: DateTimeOffset){
        account(id: $id){
            id
            healths{
                mostUsedIntegrations {
                    count
                    integration {
                        id
                        name
                    }
                }
                mostViewedDashboards(start: $start) {
                    view
                    dashboard {
                        id
                        title
                        type {
                            id
                            name
                        }
                    }
                }
                dashboardsUsage(start: $start) {
                    date
                    dbCount
                    maxDbCount
                }
                integrationsUsage(start: $start) {
                    date
                    errorsAuth
                    nbIntegrations
                }
                sourcesUsage(start: $start) {
                    date
                    errorsSources
                    nbSourcesConnected
                }
            }
        }
    }
`;