import {DTGraphTypes, Models} from "@dashthis/common";
import {Integration as IntegrationUi} from "@dashthis/ui";

interface IIntegration extends DTGraphTypes.Integration {
  Icon: IntegrationUi.IntegrationIcon;
}

export type IntegrationModel = Models.Types.Model<IIntegration>;

export const Integration: Models.Types.ModelCtr<DTGraphTypes.Integration, IIntegration> = (data) => ({
  ...data,
  get Icon() {
    return IntegrationUi.integrationIconsById[data.typeId!];
  }
});