import React from "react";
import SelectDashboard from "../../../../../../../medias/svg/selectDashboard.inline.svg";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {fileTemplatesSelectItemDescriptionStyle, fileTemplatesSelectItemPlaceholderStyle, fileTemplatesSelectItemStyle, fileTemplatesSelectItemTitleStyle} from "../list/styles/fileTemplatesSelectItem.style";

interface IProps {
}

export const FileTemplatesSelectItem = (props: IProps) => {
  const css = Styles.Hooks.useClassName(fileTemplatesSelectItemStyle);
  const titleCss = Styles.Hooks.useClassName(fileTemplatesSelectItemTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(fileTemplatesSelectItemDescriptionStyle);
  const placeholderCss = Styles.Hooks.useClassName(fileTemplatesSelectItemPlaceholderStyle);

  return (
    <div className={css}>
      <p className={titleCss}>{formatMessage("Select a item")}</p>
      <SelectDashboard className={placeholderCss}/>
      <p className={descriptionCss}>{formatMessage("To view these properties")}</p>
    </div>
  );
};


export default FileTemplatesSelectItem;
