import {DocumentNode} from "graphql";
import {QueryResult, useQuery} from "@apollo/client";
import {useCallback, useMemo} from "react";
import md5 from "md5";
import {omit} from "lodash";
import {DTGraphTypes, Hooks} from "@dashthis/common";

export type ListAccountsBaseVariables = DTGraphTypes.QueryAccountsArgs

type AccountsResponse = {
  accounts: {
    count: number,
    pages: number,
    page: number
    accounts: DTGraphTypes.Account[]
  }
};

const canFetchMore = <V extends ListAccountsBaseVariables, >(response: QueryResult<AccountsResponse, V>, page: number, limit: number): boolean => {
  const pages = !response.loading && response.error == null && response.data?.accounts.pages ? response.data.accounts.pages : 0;
  const count = !response.loading && response.error == null && response.data?.accounts.count ? response.data.accounts.count : 0;

  if (count <= limit) {
    return false;
  } else if (page < pages) {
    return true;
  } else if (page === pages) {
    return false;
  }

  return false;
};

type ListAccounts = {
  loading: boolean,
  id: string,
  total: number,
  accounts: DTGraphTypes.Account[],
  pages: number,
  fetchMore?: () => Promise<void>
}
export const useListAccounts = <V extends ListAccountsBaseVariables, >(variables: V, query: DocumentNode): ListAccounts => {
  const response = useQuery<AccountsResponse, V>(query, {
    variables
  });
  const fetchMore = useCallback(async (p: number) => {
    await response.fetchMore({
      variables: {
        page: p
      },
      updateQuery: (prev: AccountsResponse, {fetchMoreResult}) => {
        if (!fetchMoreResult) {
          return prev;
        }

        return {
          accounts: {
            accounts: [...prev.accounts.accounts, ...fetchMoreResult.accounts.accounts],
            page: p,
            count: fetchMoreResult.accounts.count,
            pages: fetchMoreResult.accounts.pages,
            __typename: "Accounts"
          }
        };
      }
    });
  }, [canFetchMore]);
  const id = useMemo(() => {
    return md5(`${query.loc!.source.body}-${JSON.stringify(omit(variables, ["page"]))}`);
  }, [query.loc!.source.body, omit(variables, ["page"])]);
  const [page, setPage] = Hooks.usePersistedRef(id, 0);

  return useMemo(() => {

    return {
      loading: response.loading,
      id,
      total: !response.loading && response.error == null && response.data?.accounts.count ? response.data.accounts.count : 0,
      accounts: !response.loading && response.error == null && response.data?.accounts.accounts ? response.data.accounts.accounts : [],
      pages: !response.loading && response.error == null && response.data?.accounts.pages ? response.data.accounts.pages : 0,
      fetchMore: canFetchMore(response, page.current, variables.limit!) ? async () => {
        setPage(page.current + 1);
        await fetchMore(page.current);
      } : undefined
    };
  }, [response]);
};