import {DTGraphTypes, Search, Models} from "@dashthis/common";

interface IAccountManager extends DTGraphTypes.AccountManager, Search.Interfaces.IMatchableQuery {
  fullName: string;
}

export type AccountManagerModel = Models.Types.Model<IAccountManager>;

export const AccountManager: Models.Types.ModelCtr<DTGraphTypes.AccountManager, IAccountManager> = (data) => ({
  ...data,
  get fullName(): string {
    return `${data.firstName} ${data.lastName}`;
  },
  matchQuery(query) {
    const searchableStrings = new Search.SearchableStrings(query);

    searchableStrings.add(data.title);
    searchableStrings.add(data.id);
    searchableStrings.add(data.firstName);
    searchableStrings.add(data.lastName);

    return searchableStrings.matchQuery();
  }
});