import {DTGraphTypes, Models} from "@dashthis/common";
import {Dashboard, DashboardModel} from "./Dashboard";

interface IMostViewedDashboards extends DTGraphTypes.MostViewedDashboards {
  Dashboard: DashboardModel | undefined;
}

export type MostViewedDashboardsModel = Models.Types.Model<Omit<IMostViewedDashboards, "dashboard">>;

export const MostViewedDashboards: Models.Types.ModelCtr<DTGraphTypes.MostViewedDashboards, IMostViewedDashboards> = (data) => ({
  ...data,
  get Dashboard() {
    return Models.createModel<DTGraphTypes.Dashboard, DashboardModel>(this.dashboard, Dashboard);
  }
});