import React from "react";
import {Input as DefaultInput, Styles} from "@dashthis/ui";
import {darkInputStyle, inputStyle} from "./styles/input.style";

interface IDarkInputProps extends DefaultInput.Types.IInputProps {
}

export const DarkInput = (props: IDarkInputProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, inputStyle, darkInputStyle);

  return (
    <DefaultInput.Input {...props} className={css}/>
  );
};


export default DarkInput;
