import React from "react";
import {VirtualizedList} from "@dashthis/ui";
import NoResultMessage from "../../../SearchBar/components/NoResultMessage";
import AccountInvoicesItem from "./AccountInvoicesItem";
import {InvoiceModel} from "../../../../../../models/Invoice";
import formatMessage from "format-message";

interface IProps {
  /**
   * The list of invoices in account.
   */
  invoices: InvoiceModel[];
  /**
   * Callback to select invoice
   */
  setInvoiceSelected: (invoice: InvoiceModel) => void;
  /**
   * The selected invoice
   */
  invoiceSelected: InvoiceModel | null,
  /**
   * The current query.
   */
  query: string
}

export const AccountInvoicesList = (props: IProps) => {
  const {invoices, setInvoiceSelected, invoiceSelected, query} = props;
  const handlerItemClick = (invoice: InvoiceModel) => () => {
    setInvoiceSelected(invoice);
  };
  const renderItem = (invoice: InvoiceModel, index: number) => {

    return (
      <AccountInvoicesItem
        isOdd={index % 2 === 0}
        onClick={handlerItemClick(invoice)}
        selected={invoice.isSame(invoiceSelected)}
        invoice={invoice}
      />
    );
  };
  const handleNoRowsRenderer = () => {
    return <NoResultMessage message={
      query !== ""
        ? formatMessage("Your search returned no results")
        : formatMessage("This account has no invoices.")
    }/>;
  };

  return (
    <VirtualizedList.VirtualizedList noRowsRenderer={handleNoRowsRenderer} items={invoices} estimateSize={82} keyExtractor={(i) => i.id} renderItem={renderItem}/>
  );
};


export default AccountInvoicesList;
