import gql from "graphql-tag";
import {DocumentNode} from "graphql";

export const accountFileTemplateQuery: DocumentNode = gql`
    query($id:ID!, $accountId:ID!){
        account(id:$accountId){
            id
            csvTemplate(id: $id) {
                id
                isDeleted
                dateRangeSeparator
                footerLines
                headerLines
                name
                encoding
                separator
                fields {
                    columnIndex
                    dataFormat
                    decimals
                    fieldType
                    dataType
                    id
                    lineIndex
                    name
                    sequence
                }
            }
        }
    }
`;