import {StudioCSS} from "../../../styles/types";

export const accountManagerPopoverStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-popover",
  height: 300,
  width: 250,
  display: "flex"
});

export const accountManagerPopoverArrowStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-popover-arrow",
  "&:before": {
    backgroundColor: utilities.colors("aquaHazeLight").toString()
  }
});

export const accountManagerPopoverListContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-popover-list-container",
  width: "100%"
});

export const accountManagerPopoverSearchInputStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-popover-search-input",
  "&[class*=input-search-field]": {
    borderRadius: 2,
    backgroundColor: utilities.colors("aquaHazeLight").toString(),
    height: 35
  }
});
