import React from "react";
import {Label as DefaultLabel, Styles} from "@dashthis/ui";
import {labelStyle} from "./styles/label.style";

interface IProps extends DefaultLabel.Types.ILabelProps {
}

export const Label = (props: IProps) => {
  const css = Styles.Hooks.useClassNameWithThoseOfProps(props, labelStyle);

  return (
    <DefaultLabel.Label {...props} className={css}/>
  );
};


export default Label;
