import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import React, {useCallback, useEffect} from "react";
import {Enums as StudioEnum} from "@dashthis/studio-common";
import {useEndpointsServiceContext} from "../../../services/hooks/useEndpointsServiceContext";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";

export const useRunAccountManagementTask = () => {
  const eventServiceContext = useEventServiceContext();
  const endpointsServiceContext = useEndpointsServiceContext();
  const listener = useCallback(() => {
    const hideNotification = Services.toastNotificationService.display(<Notification.LoadingNotification>{formatMessage("Sending broker message.")}</Notification.LoadingNotification>);


    fetch(`${endpointsServiceContext.taskRunner}SendBrokerMessage?unitOfWorkType=4&queuePriorityLevel=0&label=ACCOUNT_MANAGEMENT`, {
      method: "POST",
      mode: "no-cors",
      headers: {
        "Accept": "application/json",
        "Access-Control-Allow-Origin": "*"
      }
    }).then(() => {
      Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("Message sent successfully. Broker now processed account management task")}</Notification.SuccessNotification>);
    }).catch((e) => {
      Services.clientService.Error.displayError(e);
    }).finally(() => {
      hideNotification();
    });
  }, []);

  useEffect(() => {
    eventServiceContext.on(StudioEnum.IPCChannelEnum.OperationsRunAccountManagement, listener);

    return () => {
      eventServiceContext.removeListener(StudioEnum.IPCChannelEnum.OperationsRunAccountManagement, listener);
    };
  }, []);
};