import React, {Fragment} from "react";
import {Gravatar} from "./Gravatar";
import {Icon} from "../../../../../components";
import {Plan} from "./Plan";
import {ActivityView} from "./ActivityView";
import {AccountManager} from "./AccountManager";
import {Styles} from "@dashthis/ui";
import {itemCompanyContainerStyle, itemCompanyIconStyle, itemCompanyNameStyle, itemEmailStyle, itemGravatarContainerStyle, itemGravatarStyle} from "./styles/itemRowStyle";
import {AccountModel} from "../../../../../models/Account";
import {EmptyUser} from "../../../../../models/User";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const ItemContent = React.memo<IProps>((props: IProps) => {
  const {account} = props;
  const companyIconCss = Styles.Hooks.useClassName(itemCompanyIconStyle);
  const gravatarCss = Styles.Hooks.useClassName(itemGravatarStyle);
  const gravatarContainerCss = Styles.Hooks.useClassName(itemGravatarContainerStyle);
  const companyNameCss = Styles.Hooks.useClassName(itemCompanyNameStyle);
  const companyContainerCss = Styles.Hooks.useClassName(itemCompanyContainerStyle);
  const emailCss = Styles.Hooks.useClassName(itemEmailStyle);
  const creator = account.Creator || EmptyUser;

  return (
    <Fragment>
      <div className={gravatarContainerCss}>
        <Gravatar className={gravatarCss} user={creator}/>
        <span className={emailCss}>{creator.email}</span>
        <div className={companyContainerCss}>
          <Icon.Icon className={companyIconCss} icon={Icon.Enums.Icons.Company}/>
          <span className={companyNameCss}>{account.CompanyName}</span>
        </div>
      </div>
      <div>
        <Plan account={account}/>
      </div>
      <ActivityView account={account}/>
      <div>
        <AccountManager account={account}/>
      </div>
    </Fragment>
  );
});


export default ItemContent;
