import React, {Fragment} from "react";
import {HeaderItem} from "../HeaderItem";
import formatMessage from "format-message";
import AccountItem from "../Accounts/AccountItem";
import UserItem from "./UserItem";
import {AccountModel} from "../../../../../../models/Account";
import {OpenAccounts, OpenUser} from "../../../../../../states/actions";
import {Styles} from "@dashthis/ui";
import {usersStyle} from "./styles/userItem.Style";
import {UserModel} from "../../../../../../models/User";

interface IProps {
  /**
   * The list of account to display.
   */
  accounts: AccountModel[];
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  /**
   * Count of account found
   */
  count: number
  /**
   * Number of total account found
   */
  total: number,
  /**
   *
   */
  openUser: OpenUser
}

export const Users = (props: IProps) => {
  const {accounts, openAccounts, count, total, openUser} = props;
  const handleDoubleClick = (account: AccountModel, e: React.MouseEvent) => {
    openAccounts(new Set([account.id!]));
    e.stopPropagation();
  };
  const handleUserDoubleClick = (account: AccountModel, user: UserModel) => (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    openUser(account.id!, user.id!);
  };
  const css = Styles.Hooks.useClassName(usersStyle);

  return (
    <Fragment>
      <HeaderItem total={total} count={count} title={formatMessage("Users")}/>
      {accounts.map((account) => (
        <AccountItem className={css} onDoubleClick={handleDoubleClick} account={account} key={account.id!}>
          {account.Users.map((user) => (
            <UserItem onDoubleClick={handleUserDoubleClick(account, user)} key={user.id!} user={user}/>
          ))}
        </AccountItem>
      ))}
    </Fragment>
  );
};


export default Users;
