import React from "react";
import {AccountNavigationBarItemsEnum} from "./enums/AccountNavigationBarItemsEnum";
import {AccountModel} from "../../../../models/Account";
import {AccountHealth} from "./Sections/Health/AccountHealth";
import {AccountUsers} from "./Sections/Users/AccountUsers";
import {AccountInvoices} from "./Sections/Invoices/AccountInvoices";
import {AccountPlan} from "./Sections/Plan/AccountPlan";
import {AccountRecurrentPayments} from "./Sections/RecurrentPayments/AccountRecurrentPayments";
import {AccountStatusHistory} from "./Sections/Status/AccountStatusHistory";
import {AccountProperties} from "./Sections/Properties/AccountProperties";
import {AccountDashboards} from "./Sections/Dashboards/Dashboards/AccountDashboards";
import {AccountActions} from "./Sections/Actions/AccountActions";
import {FileTemplates} from "./Sections/FileTemplates/FileTemplates";
import AccountFeatures from "./Sections/Feature/AccountFeatures";
import DashboardsReport from "./Sections/DashboardsReport/DashboardsReport";

interface IProps {
  /**
   * The current section selected.
   */
  section: AccountNavigationBarItemsEnum;
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountSwitchSection = (props: IProps) => {
  const {section, account} = props;

  switch (section) {
    case AccountNavigationBarItemsEnum.Health:
      return (<AccountHealth account={account}/>);
    case AccountNavigationBarItemsEnum.Invoices:
      return (<AccountInvoices account={account}/>);
    case AccountNavigationBarItemsEnum.Plan:
      return (<AccountPlan account={account}/>);
    case AccountNavigationBarItemsEnum.DashboardReport:
      return (<DashboardsReport account={account}/>);
    case AccountNavigationBarItemsEnum.Properties:
      return (<AccountProperties account={account}/>);
    case AccountNavigationBarItemsEnum.RecurrentPayments:
      return (<AccountRecurrentPayments account={account}/>);
    case AccountNavigationBarItemsEnum.Status:
      return (<AccountStatusHistory account={account}/>);
    case AccountNavigationBarItemsEnum.Users:
      return (<AccountUsers account={account}/>);
    case AccountNavigationBarItemsEnum.Dashboards:
      return (<AccountDashboards account={account}/>);
    case AccountNavigationBarItemsEnum.Actions:
      return (<AccountActions account={account}/>);
    case AccountNavigationBarItemsEnum.FileTemplates:
      return (<FileTemplates account={account}/>);
    case AccountNavigationBarItemsEnum.Features:
      return (<AccountFeatures account={account}/>);
  }
};


export default AccountSwitchSection;
