import React from "react";
import {AccountModel} from "../../../../../../models/Account";
import AccountRecurrentPaymentsItem from "./AccountRecurrentPaymentsItem";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountRecurrentPaymentsContainerStyle, accountRecurrentPaymentsStyle} from "./styles/accountRecurrentPayments.style";
import numeral from "numeral";

interface IProps {
  /**
   * The account model.
   */
  account: AccountModel;
}

export const AccountRecurrentPayments = (props: IProps) => {
  const {account} = props;
  const css = Styles.Hooks.useClassName(accountRecurrentPaymentsStyle);
  const containerCss = Styles.Hooks.useClassName(accountRecurrentPaymentsContainerStyle);

  return (
    <div className={css}>
      <div className={containerCss}>
        <AccountRecurrentPaymentsItem title={formatMessage("Payment frequency")} content={account.RecurrentPayment!.frequency!}/>
        <AccountRecurrentPaymentsItem title={formatMessage("Amount")} content={numeral(account.RecurrentPayment!.amount!).format("$0.00")}/>
        <AccountRecurrentPaymentsItem title={formatMessage("Vault Id")} content={account.RecurrentPayment!.vaultId!}/>
        <AccountRecurrentPaymentsItem title={formatMessage("Last payment")} content={account.RecurrentPayment!.dateFormatted("lastPaymentDate")}/>
        <AccountRecurrentPaymentsItem title={formatMessage("Next payment date")} content={account.RecurrentPayment!.dateFormatted("nextPaymentDate")}/>
      </div>
    </div>
  );
};

export default AccountRecurrentPayments;
