import React, {ReactNode, useState} from "react";
import {connectToDrawerSheetOverlayStyle, connectToDrawerStyle, connectToDrawerTitleStyle} from "../styles/connectToDrawer.style";
import {Box, Sheet, Styles} from "@dashthis/ui";
import Item from "./Item";
import {Enums} from "@dashthis/common";
import formatMessage from "format-message";
import {connectToDrawerItemsStyle} from "../styles/connectToItem.style";
import ConnectForm from "./ConnectForm";


interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
}

const itemIsDisabledForKey = (key: Enums.EnvsEnum, selected: Enums.EnvsEnum | null, loading: boolean): boolean => {
  if (loading && selected !== key) {
    return true;
  }

  return selected != null && selected !== key;
};

export const ConnectToDrawer = (props: IProps) => {
  const css = Styles.Hooks.useClassName(connectToDrawerStyle);
  const titleCss = Styles.Hooks.useClassName(connectToDrawerTitleStyle);
  const itemsCss = Styles.Hooks.useClassName(connectToDrawerItemsStyle);
  const sheetOverlayCss = Styles.Hooks.useClassName(connectToDrawerSheetOverlayStyle);
  const [selected, setSelected] = useState<Enums.EnvsEnum | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const {SheetComponent, manager, closeSheet, showSheet} = Sheet.Hooks.useSheet();
  const handleSetSelected = (env: Enums.EnvsEnum | null) => {
    setSelected(env);
    showSheet();
  };

  return (
    <div className={css}>
      <Box.Box spaceBottom={"l"} spaceTop="l" spaceLeft="l" spaceRight="l" spaceMode="padding">
        <div>
          <p className={titleCss}>Connections</p>
          <div className={itemsCss}>
            <Item setLoading={setLoading} disabled={itemIsDisabledForKey(Enums.EnvsEnum.Production, selected, loading)} setSelected={handleSetSelected} selected={selected === Enums.EnvsEnum.Production} env={Enums.EnvsEnum.Production} title={formatMessage("Production")} url="https://dashthis.com"/>
            <Item setLoading={setLoading} disabled={itemIsDisabledForKey(Enums.EnvsEnum.PreProduction, selected, loading)} setSelected={handleSetSelected} selected={selected === Enums.EnvsEnum.PreProduction} env={Enums.EnvsEnum.PreProduction} title={formatMessage("Preprod")} url="https://preprod.dashthis.com"/>
            <Item setLoading={setLoading} disabled={itemIsDisabledForKey(Enums.EnvsEnum.Staging, selected, loading)} setSelected={handleSetSelected} selected={selected === Enums.EnvsEnum.Staging} env={Enums.EnvsEnum.Staging} title={formatMessage("Staging")} url="https://staging.dashthis.com"/>
            <Item setLoading={setLoading} disabled={itemIsDisabledForKey(Enums.EnvsEnum.Development, selected, loading)} setSelected={handleSetSelected} selected={selected === Enums.EnvsEnum.Development} env={Enums.EnvsEnum.Development} title={formatMessage("Develop")} url="https://develop.dashthis.com"/>
            <Item setLoading={setLoading} disabled={itemIsDisabledForKey(Enums.EnvsEnum.Local, selected, loading)} setSelected={handleSetSelected} selected={selected === Enums.EnvsEnum.Local} env={Enums.EnvsEnum.Local} title={formatMessage("Local")} url="http://localhost:4220"/>
          </div>
        </div>
      </Box.Box>
      <SheetComponent overlayClassName={sheetOverlayCss} manager={manager}>
        <ConnectForm env={selected!} onCancel={() => {
          setSelected(null);
          closeSheet();
        }}/>
      </SheetComponent>
    </div>
  );
};


export default ConnectToDrawer;
