import {useCallback, useMemo, useState} from "react";
import {sort} from "fast-sort";
import {get} from "lodash";

type Direction = {
  direction: "asc" | "desc",
}
type SortField = {
  field: string,
  display: string
}

type SortHeader<Item> = {
  onSortChange: (field: string, direction: "asc" | "desc") => void;
  sortedItems: Item[],
  selectedField: SortField & Direction
}

type InitialState = {
  field: string
} & Direction

export const useSortHeader = <Item>(initialState: InitialState, items: Item[], sortFields: SortField[]): SortHeader<Item> => {
  const [sortBy, setSortBy] = useState(initialState);
  const sortChange = useCallback<SortHeader<Item>["onSortChange"]>((field, direction) => {
    setSortBy({field, direction});
  }, [setSortBy]);
  const sortedItems = useMemo(() => {
    if (sortBy.direction === "asc") {
      return sort(items).asc((d) => get(d, sortBy.field));
    }

    return sort(items).desc((d) => get(d, sortBy.field));
  }, [sortBy, items]);
  const getDisplayField = (field:string): string => sortFields.find((f) => f.field === field)?.display || "";
  const getSelectedField = (): SortField & Direction => {
    const field = sortFields.find((f) => f.field === sortBy.field);

    if (field === undefined) {
      return {
        ...initialState,
        display: getDisplayField(initialState.field)
      };
    }

    return {
      ...sortBy,
      display: getDisplayField(sortBy.field)
    };
  };

  return {
    onSortChange: sortChange,
    sortedItems,
    selectedField: getSelectedField()
  };
};