import {isEmpty} from "lodash";
import React from "react";
import {Icon, Styles, Taskbar} from "@dashthis/ui";
import {TaskBarSelectedItem, TaskBarSelectedItemAccount} from "../../../../../../states/types";
import {taskbarItemStyle} from "../../styles/taskbarItem.style";
import {useLoadAccountDetails} from "../../../../../../hooks/useLoadAccountDetails";
import {TaskBarItemTypeEnum} from "../../../../../../enums/TaskBarItemTypeEnum";
import {AccountModel} from "../../../../../../models/Account";

export type Props = {
  /**
   * Callback to close a opened account.
   */
  closeAccounts: (accounts: Set<string>) => void,
  /**
   * The account id.
   */
  accountId: string,
  /**
   * Indicate which item are select in taskbar.
   */
  selected: TaskBarSelectedItem,
  /**
   * Callback when item are clicked.
   */
  onClick: (item: TaskBarSelectedItem) => void,
};

export const OpenedAccountsTaskbarItem = (props: Props) => {
  const {closeAccounts, accountId, selected, onClick} = props;
  const {matcher} = useLoadAccountDetails(accountId);
  const handleCloseAccountClick = () => {
    closeAccounts(new Set([accountId]));
  };
  const handleAccountClick = () => {
    onClick({
      id: accountId,
      type: TaskBarItemTypeEnum.Account
    });
  };
  const getCompanyNameOrEmailCreator = (account: AccountModel): string => {
    const companyName = account.companyName!;
    const creator = account.Creator!;

    return !isEmpty(companyName) ? companyName : creator.email;
  };
  const taskbarItemCss = Styles.Hooks.useClassName(taskbarItemStyle);
  const action = (<Taskbar.TaskbarItemAction onClick={handleCloseAccountClick} icon={Icon.Enums.Icons.Clear}/>);

  return matcher({
    onAccountDetailsLoading: () => <Taskbar.TaskbarItemLoading/>,
    onAccountDetailsLoaded: (account) => (
      <Taskbar.TaskbarItem
        className={taskbarItemCss}
        action={action}
        text={getCompanyNameOrEmailCreator(account)}
        selected={(selected as TaskBarSelectedItemAccount).id === accountId}
        onClick={handleAccountClick}
      />
    ),
    onLoadAccountDetailsError: (error) => (
      <Taskbar.TaskbarItemError
        action={action}
        error={error!}
      />
    )
  });

};


export default OpenedAccountsTaskbarItem;