import {StudioCSS} from "../../../../../../../styles/types";

export const accountPlanListItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item",
  display: "grid",
  gridTemplateColumns: "auto auto",
  padding: utilities.space("s"),
  borderBottom: `1px solid ${utilities.colors("athensGray")}`,
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountPlanListItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item-selected",
  background: utilities.colors("chambray").alpha(.4).string()
});

export const accountPlanListItemRightStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item-right",
  justifySelf: "flex-end"
});

export const accountPlanListItemNameStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item-name",
  ...utilities.fontStyle({
    weight: "n",
    size: "regular"
  })
});

export const accountPlanListItemOtherTextStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item-other-text",
  ...utilities.fontStyle({
    weight: "n",
    color: "scorpion",
    size: "tiny"
  }),
  strong: {
    ...utilities.fontStyle({
      weight: "b"
    })
  }
});

export const accountPlanListItemPriceStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-list-item-price",
  ...utilities.fontStyle({
    weight: "b",
    size: "regular"
  })
});
