import {Dialog, Styles, Window} from "@dashthis/ui";
import {Types} from "@dashthis/common";
import React, {useEffect, useRef} from "react";
import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {Enums} from "@dashthis/studio-common";
import {newUpdateWindowStyle} from "../styles/newUpdateWindow.style";
import NewUpdateContent from "./NewUpdateContent";

const FiveMinutes = 300000;

export interface INewUpdateWindowProps {
}

export const NewUpdateWindow = (props: INewUpdateWindowProps) => {
  const {ModalComponent, manager, showModal, closeModal} = Dialog.Hooks.useModal();
  const checkTimer = useRef<any>();
  const eventService = useEventServiceContext();
  const handleNewUpdateAvailable = () => {
    showModal();
  };
  const size: Types.Geometry.Size = {
    width: 525,
    height: 0
  };
  const frameCss = Styles.Hooks.useClassName(newUpdateWindowStyle);

  eventService.on(Enums.IPCChannelEnum.NewUpdateAvailable, handleNewUpdateAvailable);

  useEffect(() => {
    checkTimer.current = setInterval(() => {
      eventService.send(Enums.IPCChannelEnum.CheckForUpdatesAndNotify);
    }, FiveMinutes);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.NewUpdateAvailable, handleNewUpdateAvailable);
      clearInterval(checkTimer.current);
    };
  }, []);

  return (
    <ModalComponent manager={manager}>
      <Window.Frame className={frameCss} size={size}>
        <NewUpdateContent onClose={closeModal}/>
      </Window.Frame>
    </ModalComponent>
  );
};


export default NewUpdateWindow;
