import React from "react";
import {Styles, VirtualizedList, Popover} from "@dashthis/ui";
import {AccountManagerModel} from "../../models/AccountManager";
import {accountManagersListGroupItemStyle, accountManagersListItemSelectedStyle, accountManagersListItemStyle} from "./styles/accountManagersList.style";
import {sort} from "fast-sort";
import formatMessage from "format-message";

interface IProps {
  accountManagers: AccountManagerModel[];
  accountManager?: AccountManagerModel;
  query: string;
  onAccountManagerClick: (accountManager: AccountManagerModel) => void;
}

type GroupType = {
  type: "group",
  id: string,
  title: string
}
type ItemType = {
  type: "item",
  id: string,
  accountManager: AccountManagerModel
}
type Items = (GroupType | ItemType)[];


export const AccountManagersList = (props: IProps) => {
  const {accountManagers, accountManager, query, onAccountManagerClick} = props;
  const itemCss = Styles.Hooks.useClassName(accountManagersListItemStyle);
  const itemSelectedCss = Styles.Hooks.useClassName(accountManagersListItemSelectedStyle);
  const itemGroupCss = Styles.Hooks.useClassName(accountManagersListGroupItemStyle);
  const popoverState = Popover.Hooks.useGetPopoverStateContext();
  const groupByTypeAndSort = (managers: AccountManagerModel[], predicate: (a: AccountManagerModel) => boolean, groupTitle: string): Items => {
    const items: Items = sort(managers.filter((a) => predicate(a))).asc((a) => a.fullName).map<ItemType>((a) => ({
      type: "item",
      id: a.id!,
      accountManager: a
    }));

    if (items.length === 0) {
      return [];
    }

    return [{
      type: "group",
      id: groupTitle,
      title: groupTitle
    }, ...items];
  };
  const getAccountManagerList = (managers: AccountManagerModel[]): Items => {
    return [
      ...groupByTypeAndSort(managers, (a) => a.isInternal, formatMessage("Internal")),
      ...groupByTypeAndSort(managers, (a) => !a.isInternal, formatMessage("Partner"))
    ];
  };
  const filterAccountManager = (): AccountManagerModel[] => accountManagers.filter((a) => a.matchQuery(query));
  const renderItem = (item: GroupType | ItemType) => {
    if (item.type === "group") {
      return <div className={itemGroupCss}>{item.title}</div>;
    } else if (item.type === "item") {
      return <div onClick={(e) => {
        onAccountManagerClick(item.accountManager);
        popoverState.close();
      }} className={`${itemCss} ${accountManager?.id === item.id ? itemSelectedCss : ""}`}>{item.accountManager.fullName}</div>;
    }
  };

  return (
    <VirtualizedList.VirtualizedList<GroupType | ItemType> renderItem={renderItem} estimateSize={50} keyExtractor={(a) => a.id!} items={getAccountManagerList(filterAccountManager())}/>
  );
};

export default AccountManagersList;
