import React, {ChangeEvent, ReactNode} from "react";
import {Popover, Spinner, Styles, Stack} from "@dashthis/ui";
import {useListAccountManagers} from "../../hooks/useListAccountManagers";
import {SearchField} from "../../components";
import {accountManagerPopoverArrowStyle, accountManagerPopoverListContainerStyle, accountManagerPopoverSearchInputStyle, accountManagerPopoverStyle} from "./styles/accountManagerPopover.style";
import AccountManagersList from "./AccountManagersList";
import {AccountManagerModel} from "../../models/AccountManager";

interface IProps {
  /**
   * Component children.
   */
  children?: ReactNode;
  accountManager?: AccountManagerModel;
  onAccountManagerSelect: (accountManager: AccountManagerModel) => void;
}

export const AccountManagerPopover = (props: IProps) => {
  const {children, accountManager, onAccountManagerSelect} = props;
  const {matcher} = useListAccountManagers();
  const [search, setSearch] = React.useState("");
  const searchCss = Styles.Hooks.useClassName(accountManagerPopoverSearchInputStyle);
  const contentCss = Styles.Hooks.useClassName(accountManagerPopoverStyle);
  const arrowCss = Styles.Hooks.useClassName(accountManagerPopoverArrowStyle);
  const listContainerCss = Styles.Hooks.useClassName(accountManagerPopoverListContainerStyle);

  return (
    <Popover.Popover>
      <Popover.PopoverTrigger>
        {children}
      </Popover.PopoverTrigger>
      <Popover.PopoverContent>
        <Popover.PopoverArrow className={arrowCss}/>
        <Popover.PopoverBody className={contentCss}>
          <Stack.VStack as="div" className={listContainerCss}>
            <Stack.StackItem itemSize="auto" clearOnClick={(e: React.MouseEvent) => {
              setSearch("");
              e.stopPropagation();
            }} value={search} onChange={(e: ChangeEvent<HTMLInputElement>) => setSearch(e.target.value)} as={SearchField.SearchField} className={searchCss} placeholder="Search"/>
            <Stack.StackItem itemSize="1fr">
              {matcher({
                onAccountManagersListing: () => <Spinner.Wheel/>,
                onAccountManagersHold: () => null,
                onAccountManagersListedError: () => null,
                onAccountManagersListed: (accountManagers) => <AccountManagersList onAccountManagerClick={(a) => onAccountManagerSelect(a)} query={search} accountManager={accountManager} accountManagers={accountManagers}/>
              })}
            </Stack.StackItem>
          </Stack.VStack>
        </Popover.PopoverBody>
      </Popover.PopoverContent>
    </Popover.Popover>
  );
};

export default AccountManagerPopover;
