import {StudioCSS} from "../../../../../../styles/types";

export const planStyle: StudioCSS = (theme, utilities) => ({
  label: "plan",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gridTemplateRows: "auto",
  paddingRight: utilities.space("n")
});

export const planProgressStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-progress",
  gridColumn: 1,
  gridRow: "1 / 3"
});

export const planNameStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-name",
  gridColumn: 2,
  ...utilities.fontStyle({
    color: "primary",
    size: "regular",
    weight: "n"
  }),
  ...utilities.ellipsis()
});

export const planInfoStyle: StudioCSS = (theme, utilities) => ({
  label: "plan-info",
  gridColumn: 2,
  ...utilities.fontStyle({
    color: "scorpion",
    size: "regular",
    weight: "l"
  })
});
