import React, {useState} from "react";
import {Account} from "@dashthis/common";
import {Notification, Services} from "@dashthis/ui";
import formatMessage from "format-message";
import {AccountModel} from "../models/Account";
import {AccountParts} from "../queries/fragments/account/accountParts";

export type UseCancelAccount = { activateFeatureFlag: (toggleIsOn: boolean) => Promise<void>, processing: boolean, enabled: boolean };

export const useUpdateAccountFeatureFlag = (account: AccountModel, id: string, forcedValue?: boolean | null): UseCancelAccount => {
  const {updateAccount, loading} = Account.Hooks.useAccountUpdate(account.id!, AccountParts);
  const [enabled, setEnabled] = useState<boolean>(forcedValue == null ? false : true);

  const activateFeatureFlag: UseCancelAccount["activateFeatureFlag"] = async (toggleIsOn) => {
    const previousState = enabled;
    const hideLoadingNotification = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Updating feature flag...")}</Notification.LoadingNotification>);

    try {
      await updateAccount({
        features: [{
          id,
          forcedValue: toggleIsOn === false ? undefined : true // when toggle is off, remove the override
        }]
      });
      setEnabled(toggleIsOn);
    } catch (e) {
      Services.clientService.Error.displayError(e, formatMessage("Updating feature flag error!"));
      setEnabled(previousState);
    } finally {
      hideLoadingNotification();
    }
  };

  return {
    activateFeatureFlag,
    processing: loading,
    enabled
  };
};