import {Client, DTGraphTypes} from "@dashthis/common";
import {searchAccountQuery} from "../../../../../queries/search/searchAccounts";
import {AccountModel} from "../../../../../models/Account";
import {SearchAccountsResponse} from "./types";
import {formatAccountSearchResponse} from "./formatResponse";
import {useMemo} from "react";

type UseSearchAccounts = {
  accounts: AccountModel[],
  loading: boolean,
  error: Client.Errors.ApplicationServerError
  count: number
}

export const useSearchAccounts = (query: string): UseSearchAccounts => {
  const [data, error, loading] = Client.Hooks.useApolloQuery<DTGraphTypes.QuerySearchAccountsArgs, SearchAccountsResponse>(searchAccountQuery, {
    variables: {
      query,
      limit: 5
    }
  });

  return useMemo<UseSearchAccounts>(() => ({
    accounts: loading || error != null ? [] : formatAccountSearchResponse(data.accounts.items),
    error,
    loading,
    count: loading || error != null ? 0 : data.accounts.count
  }), [data, error, loading]);
};

export default useSearchAccounts;