import {Icon, Select as DefaultSelect, Styles} from "@dashthis/ui";
import {Select} from "../../../../../../../components";
import {DTGraphTypes} from "@dashthis/common";
import formatMessage from "format-message";
import React from "react";
import {AccountFilterCriterias, SetCriteriaValue} from "../../hooks/useAccountFilter";
import {criteriasListItemDeleteIconStyle, criteriasListItemStyle} from "../../styles/criteriasList.style";

interface IProps {
  /**
   * The default status selected.
   */
  value?: DTGraphTypes.AccountStatusGraphQl;
  /**
   * Callback when delete button are clicked.
   */
  onDeleteClick: (criteriaType: AccountFilterCriterias) => void;
  /**
   * Callback to set the value for Criteria.
   */
  setCriteriaValue: SetCriteriaValue;
}

export const StatusCriteria = (props: IProps) => {
  const {value, setCriteriaValue, onDeleteClick} = props;
  const handleDeleteClick = () => {
    onDeleteClick("status");
  };
  const handleChange = (e: DefaultSelect.Types.SelectEventTarget<DTGraphTypes.AccountStatusGraphQl>) => {
    const status = e.target.value;

    setCriteriaValue("status", status as DTGraphTypes.AccountStatusGraphQl);
  };
  const getLabelFromValue = (): string => {
    switch (value) {
      case DTGraphTypes.AccountStatusGraphQl.Active:
        return formatMessage("Active");
      case DTGraphTypes.AccountStatusGraphQl.Cancelled:
        return formatMessage("Cancelled");
      case DTGraphTypes.AccountStatusGraphQl.EndExtendTrial:
        return formatMessage("End Extend Trial");
      case DTGraphTypes.AccountStatusGraphQl.EndTrial:
        return formatMessage("End Trial");
      case DTGraphTypes.AccountStatusGraphQl.ExtendedTrial:
        return formatMessage("End Extend Trial");
      case DTGraphTypes.AccountStatusGraphQl.Inactive:
        return formatMessage("Inactive");
      case DTGraphTypes.AccountStatusGraphQl.NoStatus:
        return formatMessage("No Status");
      case DTGraphTypes.AccountStatusGraphQl.Suspend:
        return formatMessage("Suspend");
      case DTGraphTypes.AccountStatusGraphQl.ArchivedForBilling:
        return formatMessage("Archived For Billing");
      case DTGraphTypes.AccountStatusGraphQl.Trial:
        return formatMessage("Trial");
      default:
        return "";
    }
  };
  const css = Styles.Hooks.useClassName(criteriasListItemStyle);
  const deleteIconCss = Styles.Hooks.useClassName(criteriasListItemDeleteIconStyle);

  return (
    <div className={css}>
      <span>{formatMessage("By status")}</span>
      <div>
        <Select.Select placeholder={formatMessage("Select status")} label={getLabelFromValue()} value={value} onChange={handleChange}>
          <DefaultSelect.Body>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.Active}>{formatMessage("Active")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.PendingPayment}>{formatMessage("Pending Payment")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.Trial}>{formatMessage("Trial")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.ExtendedTrial}>{formatMessage("Extended Trial")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.Cancelled}>{formatMessage("Cancelled")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.EndTrial}>{formatMessage("End Trial")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.EndExtendTrial}>{formatMessage("End Extend Trial")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.Inactive}>{formatMessage("Inactive")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.Suspend}>{formatMessage("Suspend")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.ArchivedForBilling}>{formatMessage("Archived For Billing")}</DefaultSelect.Item>
            <DefaultSelect.Item value={DTGraphTypes.AccountStatusGraphQl.NoStatus}>{formatMessage("No Status")}</DefaultSelect.Item>
          </DefaultSelect.Body>
        </Select.Select>

      </div>
      <Icon.Icon onClick={handleDeleteClick} className={deleteIconCss} icon={Icon.Enums.Icons.Clear}/>
    </div>
  );
};


export default StatusCriteria;

