import {StudioCSS} from "../../../../../../../styles/types";

export const accountPlanActionsPlanStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-plan",
  background: utilities.colors("athensGray").string(),
  padding: utilities.space("n"),
  display: "grid",
  zIndex: 10,
  position: "relative",
  gridTemplateColumns: "1fr auto",
  marginBottom: utilities.space("n"),
  "&:after": {
    content: "''",
    width: 0,
    height: 0,
    borderStyle: "solid",
    borderWidth: "15px 13px 0 13px",
    borderColor: `${utilities.colors("athensGray").string()} transparent transparent transparent`,
    position: "absolute",
    bottom: -15,
    left: "calc(50% - 7.5px)"
  }
});

export const accountPlanActionsPlanNameStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-plan-name",
  ...utilities.fontStyle({
    weight: "m",
    color: "primary",
    size: "large"
  })
});

export const accountPlanActionsPlanCountStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-plan-count",
  gridColumn: "1",
  ...utilities.fontStyle({
    weight: "n",
    size: "regular",
    color: "scorpion"
  })
});

export const accountPlanActionsPlanPriceStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-plan-price",
  gridColumn: "2",
  gridRow: "1/3",
  ...utilities.fontStyle({
    weight: "b",
    size: "huge",
    color: "scorpion"
  })
});
