import {CsvTemplateModel} from "../../../../../../../models/CsvTemplate";
import {useAccountPersistedRef} from "../../../hooks/useAccountPersistedRef";
import {AccountModel} from "../../../../../../../models/Account";
import {useCallback, useEffect} from "react";
import {Hooks} from "@dashthis/common";
import {sort} from "fast-sort";
import {CsvFileModel} from "../../../../../../../models/CsvFile";
import {CsvSourceModel} from "../../../../../../../models/CsvSource";

type FileTemplatesTreeTemplateItem = {
  type: "template",
  id: string,
  template: CsvTemplateModel
};
type FileTemplatesTreeFilesItem = {
  type: "files",
  id: string,
};
type FileTemplatesTreeFileItem = {
  type: "file",
  id: string,
  template: CsvTemplateModel
  file: CsvFileModel
};
type FileTemplatesTreeSourcesItem = {
  type: "sources",
  id: string
};
type FileTemplatesTreeSourceItem = {
  type: "source",
  id: string,
  template: CsvTemplateModel
  source: CsvSourceModel
};

export type AccountFileTemplatesTreeOpenState = Map<string, boolean>;
export type FileTemplatesTreeItem = FileTemplatesTreeTemplateItem | FileTemplatesTreeFilesItem | FileTemplatesTreeFileItem | FileTemplatesTreeSourcesItem | FileTemplatesTreeSourceItem;
export type FileTemplatesTreeItems = FileTemplatesTreeItem[];

type UseAccountFileTemplatesTree = {
  isFileTemplatesAreOpen: (id: string) => boolean,
  toggleFileTemplatesOpen: (id: string) => void,
  fileTemplatesOpenState: AccountFileTemplatesTreeOpenState,
  fileTemplatesTree: FileTemplatesTreeItems
}

const filterFiles = (files: CsvFileModel[], query: string): CsvFileModel[] => {
  return query === "" ? files : files.filter((f) => f.matchQuery(query));
};
const filterSources = (sources: CsvSourceModel[], query: string): CsvSourceModel[] => {
  return query === "" ? sources : sources.filter((s) => s.matchQuery(query));
};

function* buildVirtualIntegrationList(fileTemplates: CsvTemplateModel[], openState: AccountFileTemplatesTreeOpenState, setState: (value: AccountFileTemplatesTreeOpenState) => void, query: string): IterableIterator<FileTemplatesTreeItem> {
  const fileTemplatesShorted = sort(fileTemplates).asc((f) => f.name);

  for (const fileTemplate of fileTemplatesShorted) {
    const filteredFiles = filterFiles(fileTemplate.Files, query);
    const filteredSource = filterSources(fileTemplate.Sources, query);

    if (filteredFiles.length > 0 || filteredSource.length > 0) {
      yield {
        type: "template",
        id: fileTemplate.id!,
        template: fileTemplate
      };

      if (query !== "" && !openState.has(fileTemplate.id!)) {
        openState.set(fileTemplate.id!, true);
        setState(openState);
      }

      if (openState.has(fileTemplate.id!) && openState.get(fileTemplate.id!)) {
        const filesId = `files-${fileTemplate.id}`;
        const sourcesId = `sources-${fileTemplate.id}`;

        if (filteredFiles.length > 0) {
          yield {
            type: "files",
            id: filesId
          };

          if (query !== "" && filteredFiles.length > 0 && !openState.has(filesId)) {
            openState.set(filesId, true);
            setState(openState);
          }

          if (openState.has(filesId) && openState.get(filesId)) {
            for (const file of filteredFiles) {
              yield {
                type: "file",
                id: file.uiId,
                template: fileTemplate,
                file
              };
            }
          }
        }

        if (filteredSource.length > 0) {
          yield {
            type: "sources",
            id: sourcesId
          };

          if (query !== "" && filteredSource.length > 0 && !openState.has(sourcesId)) {
            openState.set(sourcesId, true);
            setState(openState);
          }

          if (openState.has(sourcesId) && openState.get(sourcesId)) {
            for (const source of filteredSource) {
              yield {
                type: "source",
                template: fileTemplate,
                id: source.uiId,
                source
              };
            }
          }
        }
      }
    }
  }
}

export const useAccountFileTemplatesTree = (account: AccountModel, fileTemplates: CsvTemplateModel[], query: string): UseAccountFileTemplatesTree => {
  const forceUpdate = Hooks.useForceUpdate();
  const [openState, setOpenState] = useAccountPersistedRef<AccountFileTemplatesTreeOpenState>(
    `fileTemplateOpenState${account.id}`
    , new Map());
  const [openSearchState, setSearchOpenState] = useAccountPersistedRef<AccountFileTemplatesTreeOpenState>(
    `fileTemplateSearchOpenState${account.id}`
    , new Map());
  const isOpen = useCallback((id: string): boolean => {
    const state = query !== "" ? openSearchState : openState;

    return state.current.has(id) && state.current.get(id)!;
  }, [openState, openSearchState, query]);
  const toggleOpen = useCallback((id: string) => {
    const state = query !== "" ? openSearchState : openState;
    const setState = query !== "" ? setSearchOpenState : setOpenState;

    if (state.current.has(id) && state.current.get(id)) {
      state.current.set(id, false);
    } else {
      state.current.set(id, true);
    }
    setState(openState.current);
    forceUpdate();
  }, [setOpenState, openState, openSearchState, setSearchOpenState, query]);
  const buildVirtualList = (): FileTemplatesTreeItems => {
    const state = query !== "" ? openSearchState : openState;
    const setState = query !== "" ? setSearchOpenState : setOpenState;
    const list = buildVirtualIntegrationList(fileTemplates, state.current, setState, query);

    return Array.from(list) as FileTemplatesTreeItems;
  };

  useEffect(() => {
    openSearchState.current.clear();
    setSearchOpenState(openSearchState.current);
  }, [query]);

  return {
    fileTemplatesTree: buildVirtualList(),
    isFileTemplatesAreOpen: isOpen,
    toggleFileTemplatesOpen: toggleOpen,
    fileTemplatesOpenState: query !== "" ? openSearchState.current : openState.current
  };
};