import React, {Fragment, HTMLAttributes} from "react";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {accountDashboardWidgetsDetailsBreakWordStyle, accountDashboardWidgetsDetailsLabelStyle, accountDashboardWidgetsDetailsNoteLabelStyle, accountDashboardWidgetsDetailsStyle} from "./styles/accountDashboardWidgetsDetails.style";
import {AuthorizationModel} from "../../../../../../../models/Authorization";

interface IProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * The authorization model
   */
  authorization: AuthorizationModel;
}

export const AccountDashboardAuthorizationDetails = (props: IProps) => {
  const {authorization, ...rest} = props;
  const css = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsStyle);
  const labelCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsLabelStyle);
  const noteCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsLabelStyle, accountDashboardWidgetsDetailsNoteLabelStyle);
  const errorDetailCss = Styles.Hooks.useClassName(accountDashboardWidgetsDetailsBreakWordStyle);

  return (
    <div style={{overflow: "auto"}} {...rest}>
      <div className={css}>
        <label className={labelCss}>{formatMessage("Id")} <span>: {authorization.id}</span></label>
        <label className={labelCss}>{formatMessage("Name")} <span>: {authorization.name}</span></label>
        <label className={labelCss}>{formatMessage("Created at")} <span>: {authorization.dateFormatted("creationDate")}</span></label>
        <label className={labelCss}>{formatMessage("Provider Key")} <span>: {authorization.providerKey}</span></label>
        <label className={labelCss}>{formatMessage("Token 1")} <span>: {authorization.token1}</span></label>
        <label className={labelCss}>{formatMessage("Token 2")} <span>: {authorization.token2}</span></label>
        {authorization.hasError
          ? <Fragment>
            <label className={noteCss}>{formatMessage("Internal Message")} </label>
            <p className={errorDetailCss}>{authorization.SourceError!.internalMessage}</p>
            <label className={noteCss}>{formatMessage("Human Readable Message")} </label>
            <p className={errorDetailCss}>{authorization.SourceError!.humanReadableMessage}</p>
          </Fragment>
          : null
        }
      </div>
    </div>
  );
};


export default AccountDashboardAuthorizationDetails;
