import React from "react";
import {Icon, WebView} from "../../../../../../components";
import {UserModel} from "../../../../../../models/User";
import {useAppSettingsServiceContext} from "../../../../../../services/hooks/useAppSettingServiceContext";
import {Styles} from "@dashthis/ui";
import {accountUserEmulateStopButtonStyle, accountUserEmulateStyle} from "./styles/accountUserEmulate.style";
import WebViewToolBarButton from "../../../../../../components/WebView/components/WebViewToolBarButton";
import formatMessage from "format-message";
import {useEmulateAccount} from "../../../../hooks/useEmulateAccount";
import {Types} from "@dashthis/studio-common";

interface IProps {
  /**
   * The use model.
   */
  user: UserModel,
  /**
   * Callback to stop emulating user.
   */
  stopEmulate: () => void
}

export const AccountUserEmulate = (props: IProps) => {
  const {user, stopEmulate} = props;
  const css = Styles.Hooks.useClassName(accountUserEmulateStyle);
  const stopButtonCss = Styles.Hooks.useClassName(accountUserEmulateStopButtonStyle);
  const appSettingService = useAppSettingsServiceContext();
  const {
    emulateUser,
    emulateUrl
  } = useEmulateAccount();
  const onDomReady = async (view: Types.ElectronTypes.WebviewTag) => {
    const emulateSettings = appSettingService.getEmulateSettings();

    if (emulateSettings.password !== "" && emulateSettings.email !== "") {
      await view.executeJavaScript(`
        if(document.getElementById('Email') != null){
            document.getElementById('Email').value="${emulateSettings.email}";
            document.getElementById('Password').value="${emulateSettings.password}";
            document.getElementsByTagName("form")[0].submit();
        }
    `);
    }
  };
  const handleOpenInWindow = (url: string) => {
    emulateUser(user, url);
    stopEmulate();
  };

  return (
    <div className={css}>
      <WebView.WebView
        extraButtons={[(<WebViewToolBarButton className={stopButtonCss} tooltip={formatMessage("Stop emulate user")} key={1} onClick={stopEmulate} icon={Icon.Enums.Icons.WebViewStop}/>)]}
        onDomReady={onDomReady}
        partition={user.email}
        onOpenInWindow={handleOpenInWindow}
        url={emulateUrl(user)}
      />
    </div>
  );
};


export default AccountUserEmulate;
