import {StudioCSS} from "../../../styles/types";

export const AccountManagersListStyle: StudioCSS = (theme, utilities) => ({
  label: ""
});

export const accountManagersListItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-managers-list-item",
  display: "flex",
  "&:hover": {
    cursor: "pointer",
    backgroundColor: utilities.colors("athensGray").toString()
  },
  padding: `${utilities.space("s")} ${utilities.space("s")}`,
  paddingLeft: `${utilities.space("n")}`,
  alignItems: "center",
  ...utilities.fontStyle({
    size: "small"
  }),
  borderBottom: `1px solid ${utilities.colors("aquaHazeLight").toString()}`
});

export const accountManagersListGroupItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-managers-list-group-item",
  display: "flex",
  backgroundColor: utilities.colors("athensGray").toString(),
  padding: `${utilities.space("s")} ${utilities.space("s")}`,
  alignItems: "center",
  ...utilities.fontStyle({
    weight: "b",
    size: "small"
  })
});

export const accountManagersListItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-managers-list-item-selected",
  pointerEvents: "none",
  backgroundColor: utilities.colors("primary").toString(),
  color: utilities.colors("white").toString()
});
