import {StudioCSS} from "../../../../../../../../styles/types";

export const fileTemplatesTemplateItemStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-template-item",
  display: "grid",
  gridTemplateColumns: "1fr auto auto",
  gap: utilities.space("s"),
  alignItems: "center",
  padding: `${utilities.space.small} ${utilities.space.large}`,
  borderBottom: `1px solid ${utilities.colors("white").string()}`,
  background: utilities.colors("aquaHazeLight").string(),
  ...utilities.fontStyle({
    weight: "m",
    size: "regular"
  }),
  "&:hover": {
    cursor: "pointer"
  },
  span: {
    ...utilities.ellipsis()
  }
});

export const fileTemplatesTemplateItemArrowIconStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-template-item-arrow-icon",
  transition: "transform .3s",
  fill: utilities.colors("scorpion").string(),
  width: 15,
  height: 15,
  "&:hover": {
    cursor: "pointer"
  }
});

export const fileTemplatesTemplateItemArrowDownIconStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-template-item-arrow-down-icon",
  transform: "rotate(90deg)"
});

export const fileTemplatesTemplateItemViewIconStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-template-item-view-icon",
  width: 16,
  height: 16,
  background: utilities.colors("white").string(),
  fill: utilities.colors("scorpion").string(),
  padding: utilities.space("t"),
  boxSizing: "content-box",
  borderRadius: 2,
  marginLeft: utilities.space("s"),
  ":hover": {
    cursor: "pointer",
    background: utilities.colors("white").darken(.1).string()
  }
});

export const fileTemplatesTemplateItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "file-templates-template-item-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string(),
  "&:hover": {
    cursor: "default"
  }
});
