import {loginQuery} from "../../../queries/login.query";
import formatMessage from "format-message";
import {useCallback, useMemo, useState} from "react";
import {Dialog, Window} from "@dashthis/ui";
import {DTGraphTypes, Enums} from "@dashthis/common";
import {createClient} from "../../../client";

export type LoginHandler = (email: string, password: string) => Promise<DTGraphTypes.Token>;

export const useLogin = (env: Enums.EnvsEnum): [LoginHandler, boolean] => {
  const [processing, setProcessing] = useState<boolean>(false);
  const client = useMemo(() => createClient(env), [env]);
  const login = useCallback<LoginHandler>(async (email, password) => {
    setProcessing(true);

    try {
      const response = await client.query<DTGraphTypes.Token, DTGraphTypes.QueryLoginArgs>({
        fetchPolicy: "no-cache",
        query: loginQuery,
        variables: {
          email,
          password
        }
      });

      return response.data!;
    } catch (e) {
      Dialog.ApplicationDialogs.message({
        title: formatMessage("Invalid information"),
        message: formatMessage("The email address or password you entered is incorrect."),
        ui: Window.Enums.WindowStyleEnum.Error
      });
      throw e;
    } finally {
      setProcessing(false);
    }
  }, [setProcessing, client]);

  return [login, processing];
};