import React, {useMemo} from "react";
import {accountsQuery} from "../../../../../queries/account/accounts.query";
import {AccountsList} from "./AccountsList";
import {DTGraphTypes} from "@dashthis/common";
import formatMessage from "format-message";

type Props = {
  /**
   * The query for searching.
   */
  query: string
};

export const ListBySearchQuery = (props: Props) => {
  const {query} = props;
  const variables: DTGraphTypes.QueryAccountsArgs = useMemo(() => ({
    limit: 50,
    page: 0,
    query
  }), [query]);

  return (
    <AccountsList<DTGraphTypes.QueryAccountsArgs> title={formatMessage("Search")} variables={variables} query={accountsQuery}/>
  );
};


export default ListBySearchQuery;
