import {OpenedAccountsTaskbarItem} from "./OpenedAccountsTaskbarItem";
import {Taskbar} from "@dashthis/ui";
import formatMessage from "format-message";
import React from "react";
import {TaskBarSelectedItem} from "../../../../../../states/types";

type Props = {
  /**
   * The list of all open accounts.
   */
  openedAccounts: Set<string>,
  /**
   * Indicate which item are select in taskbar.
   */
  selected: TaskBarSelectedItem,
  /**
   * Callback to close a opened account.
   */
  closeAccounts: (accounts: Set<string>) => void,
  /**
   * Callback when item are clicked.
   */
  onItemClick: (item: TaskBarSelectedItem) => void,
};

export const OpenedAccountsTaskbarCategory = (props: Props) => {
  const {onItemClick, selected, closeAccounts, openedAccounts} = props;
  const title = formatMessage(`
      { count , plural ,
        =0 {}
        one {Account}
        other {Accounts} 
      }
  `, {
    count: openedAccounts.size
  });

  if (openedAccounts.size === 0) {
    return null;
  }

  return (
    <Taskbar.TaskbarCategory title={title}>
      {Array.from(openedAccounts.values()).map((id: string) => (
        <OpenedAccountsTaskbarItem key={id} onClick={onItemClick} selected={selected} accountId={id} closeAccounts={closeAccounts}/>
      ))}
    </Taskbar.TaskbarCategory>
  );
};


export default OpenedAccountsTaskbarCategory;
