import React, {FocusEventHandler, Fragment, MouseEventHandler, useState} from "react";
import {InputSearch} from "./components/InputSearch";
import {AddSearchToHistory, OpenAccounts, OpenDashboard, OpenFileTemplate, OpenUser, SetSearchQuery} from "../../../../states/actions";
import {SearchResult} from "./components/SearchResult";
import {HistorySearch} from "./components/HistorySearch";
import {Conditional, Hooks} from "@dashthis/common";
import {Styles} from "@dashthis/ui";
import {searchBarFocusedStyle} from "./components/styles/searchBar.style";

interface IProps {
  /**
   * Callback to call when you need to perform a full search.
   */
  setSearchQuery: SetSearchQuery,
  /**
   * Callback to call when you want to add new search in search history.
   */
  addSearchToHistory: AddSearchToHistory,
  /**
   * Callback to call to open an account.
   */
  openAccounts: OpenAccounts;
  openDashboard: OpenDashboard;
  openUser: OpenUser;
  openFileTemplate: OpenFileTemplate
}

export const SearchBar = (props: IProps) => {
  const {setSearchQuery, addSearchToHistory, openAccounts, openDashboard, openUser, openFileTemplate} = props;
  const [open, setOpen] = useState<boolean>(false);
  const [searchTherm, setSearchTherm] = useState<string>("");
  const [currentSearchTherm, setCurrentSearchTherm] = useState<string>("");
  const dismiss = () => {
    setSearchTherm("");
    setCurrentSearchTherm("");
    setOpen(false);
  };
  const clear = () => {
    setSearchTherm("");
    setCurrentSearchTherm("");
  };
  const handleDismiss = (e: React.MouseEvent) => {
    dismiss();
  };
  const handleViewAll = (e: React.MouseEvent) => {
    setSearchQuery(currentSearchTherm);
    dismiss();
  };
  const handleClear = (e: React.MouseEvent) => {
    clear();
  };
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTherm(e.target.value);
    setOpen(true);
    if (e.target.value === "") {
      setCurrentSearchTherm("");
    }
  };
  const handleFocus: FocusEventHandler = (e) => {
    setOpen(true);
  };
  const handleClick: MouseEventHandler = (e) => {
    setOpen(true);
  };
  const handleHistoryClick = (history: string) => {
    setCurrentSearchTherm(history);
    setSearchTherm(history);
  };
  const handleOpenAccounts: OpenAccounts = (accounts) => {
    openAccounts(accounts);
    dismiss();
  };
  const handleOpenDashboard: OpenDashboard = (accounts, dashboard) => {
    openDashboard(accounts, dashboard);
    dismiss();
  };
  const handleOpenUser: OpenUser = (accounts, user) => {
    openUser(accounts, user);
    dismiss();
  };
  const handleOpenFileTemplate: OpenFileTemplate = (accounts, fileTemplate) => {
    openFileTemplate(accounts, fileTemplate);
    dismiss();
  };
  const searchBarCss = Styles.Hooks.useClassName(
    Conditional.is(open, searchBarFocusedStyle)
  );

  Hooks.useEventListener<KeyboardEvent>("keydown", (e) => {
    if ((e.code === "Enter" || e.code === "NumpadEnter") && open) {
      setCurrentSearchTherm(searchTherm);
      addSearchToHistory(searchTherm);
    }
    if (e.code === "Escape" && open) {
      dismiss();
    }
  }, window);

  return (
    <Fragment>
      <InputSearch
        isOpen={open}
        onViewAll={handleViewAll}
        currentSearch={currentSearchTherm}
        onDismiss={handleDismiss}
        onClear={handleClear}
        onClick={handleClick}
        onFocus={handleFocus}
        className={searchBarCss}
        value={searchTherm}
        onChange={handleChange}
      />
      {open
        ? currentSearchTherm !== ""
          ? <SearchResult
            openFileTemplate={handleOpenFileTemplate}
            openUser={handleOpenUser}
            openDashboard={handleOpenDashboard}
            openAccounts={handleOpenAccounts}
            query={currentSearchTherm}
          />
          : <HistorySearch onHistoryClick={handleHistoryClick} query={searchTherm}/>
        : null
      }
    </Fragment>
  );
};


export default SearchBar;
