import {StudioCSS} from "../../../../../../../../styles/types";

export const accountDashboardWidgetsDetailsStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-details",
  padding: utilities.space("n")
});

export const accountDashboardWidgetsDetailsLabelStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-details-label",
  paddingBottom: utilities.space("s"),
  display: "block",
  ...utilities.fontStyle({
    weight: "b",
    size: "regular"
  }),
  span: {
    ...utilities.fontStyle({weight: "n"}),
    overflowWrap: "break-word",
    wordWrap: "break-word",
    hyphens: "auto"
  }
});

export const accountDashboardWidgetsDetailsNoteLabelStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-details-note-label",
  paddingTop: utilities.space("s")
});

export const accountDashboardWidgetsDetailsBreakWordStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-details-break-word",
  ...utilities.breakWord()
});

export const accountDashboardWidgetsDetailsResetDateContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-dashboard-widgets-details-reset-date-Container",
  padding: utilities.space("n"),
  paddingTop: utilities.space("l"),
  display: "grid",
  gridTemplateColumns: "1fr auto",
  alignItems: "center",
  borderTop: `1px solid ${utilities.colors("aquaHaze").string()}`
});
