import React from "react";
import {Icon, NavigationBar} from "../../../../../../../components";
import formatMessage from "format-message";
import {Tooltip} from "@dashthis/ui";
import {DashboardNavigationBarItemsEnum} from "../enums/DashboardNavigationBarItemsEnum";

interface IProps {
  /**
   * The current item selected
   */
  selectedItem: DashboardNavigationBarItemsEnum,
  /**
   * Callback to change the selected item in navigation bar.
   */
  setSelectedItem: (item: DashboardNavigationBarItemsEnum) => void
}

export const AccountDashboardNavigationBar = (props: IProps) => {
  const {selectedItem, setSelectedItem} = props;
  const handleBarItemClick = (item: DashboardNavigationBarItemsEnum) => () => {
    setSelectedItem(item);
  };

  return (
    <NavigationBar.NavigationBar>
      <NavigationBar.NavigationBarItem
        tooltipPlacement={Tooltip.Enums.TooltipPlacementEnum.Left}
        selected={selectedItem === DashboardNavigationBarItemsEnum.Health}
        onClick={handleBarItemClick(DashboardNavigationBarItemsEnum.Health)}
        tooltips={formatMessage("Dashboard Health")}
        icon={Icon.Enums.Icons.NavigationHealth}
      />
      <NavigationBar.NavigationBarItem
        tooltipPlacement={Tooltip.Enums.TooltipPlacementEnum.Left}
        selected={selectedItem === DashboardNavigationBarItemsEnum.Properties}
        onClick={handleBarItemClick(DashboardNavigationBarItemsEnum.Properties)}
        tooltips={formatMessage("Dashboard Properties")}
        icon={Icon.Enums.Icons.NavigationProperties}
      />
      <NavigationBar.NavigationBarItem
        tooltipPlacement={Tooltip.Enums.TooltipPlacementEnum.Left}
        selected={selectedItem === DashboardNavigationBarItemsEnum.Widgets}
        onClick={handleBarItemClick(DashboardNavigationBarItemsEnum.Widgets)}
        tooltips={formatMessage("Dashboard Widgets")}
        icon={Icon.Enums.Icons.NavigationWidgets}
      />
      <NavigationBar.NavigationBarItem
        tooltipPlacement={Tooltip.Enums.TooltipPlacementEnum.Left}
        selected={selectedItem === DashboardNavigationBarItemsEnum.View}
        onClick={handleBarItemClick(DashboardNavigationBarItemsEnum.View)}
        tooltips={formatMessage("View Dashboard")}
        icon={Icon.Enums.Icons.NavigationView}
      />
    </NavigationBar.NavigationBar>
  );
};

export default AccountDashboardNavigationBar;
