import React, {MouseEventHandler} from "react";
import {Button} from "../../../components";
import {Stack, Styles} from "@dashthis/ui";
import {newUpdateContentLeftStyle, newUpdateContentStyle, newUpdateContentUpdateIconStyle, newUpdateContentUpdateTextStyle} from "../styles/newUpdateContent.style";
import formatMessage from "format-message";
import UpdateIcon from "../../../medias/svg/updateIcon.inline.svg";
import {useOpenUrlServiceContext} from "../../../services/hooks/useOpenUrlServiceContext";
import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {Enums} from "@dashthis/studio-common";

interface IProps {
  /**
   * Callback to call to close window.
   */
  onClose: () => void;
}

export const NewUpdateContent = (props: IProps) => {
  const {onClose} = props;
  const eventService = useEventServiceContext();
  const css = Styles.Hooks.useClassName(newUpdateContentStyle);
  const leftCss = Styles.Hooks.useClassName(newUpdateContentLeftStyle);
  const updateIconCss = Styles.Hooks.useClassName(newUpdateContentUpdateIconStyle);
  const updateTextCss = Styles.Hooks.useClassName(newUpdateContentUpdateTextStyle);
  const {openUrl} = useOpenUrlServiceContext();
  const handleDownloadNowClick: MouseEventHandler = async () => {
    await openUrl("https://github.com/DashThis/Studio/releases");
    eventService.send(Enums.IPCChannelEnum.QuitApp);
  };

  return (
    <div className={css}>
      <div className={leftCss}>
        <UpdateIcon className={updateIconCss}/>
      </div>
      <div className={updateTextCss}>
        <p>{formatMessage("New Update Available")}</p>
        <p>{formatMessage("New Version of Studio 3 is available to download.")}</p>
        <p>{formatMessage("To continue to use Studio 3, please update your copy by downloading the new version.")}</p>
        <Stack.HStack gap={10} justifyContent={Stack.Enums.JustifyContentEnum.End}>
          <Button.Button onClick={onClose}>{formatMessage("later")}</Button.Button>
          <Button.Button onClick={handleDownloadNowClick}>{formatMessage("Download Now")}</Button.Button>
        </Stack.HStack>
      </div>
    </div>
  );
};


export default NewUpdateContent;
