import {StudioCSS} from "../../../styles/types";

export const accountManagerPickerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-picker",
  position: "relative",
  "&:hover": {
    cursor: "pointer"
  }
});

export const accountManagerPickerImageContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-picker-image-container",
  position: "relative"
});

export const accountManagerPickerMenuIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-picker-menu-icon",
  position: "absolute",
  top: "48%",
  right: -8,
  background: utilities.colors("white").toString(),
  width: 24,
  height: 24,
  borderRadius: "50%",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  "svg": {
    width: 12,
    height: 12,
    paddingTop: 2
  }
});

export const accountManagerNamePickerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-manager-name-picker",
  textAlign: "center",
  "span:nth-of-type(1)": {
    display: "block",
    ...utilities.fontStyle({
      weight: "b",
      size: "regular"
    })
  },
  "span:nth-of-type(2)": {
    display: "block",
    ...utilities.fontStyle({
      weight: "n",
      size: "small"
    })
  }
});