import {StudioCSS} from "../../../../../../../styles/types";

export const accountActionsItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item",
  borderBottom: `1px solid ${utilities.colors("aquaHaze").string()}`,
  padding: `${utilities.space("s")} ${utilities.space("n")}`,
  position: "relative",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  alignItems: "center"
});

export const accountActionsItemRedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-red",
  cursor: "not-allowed",
  color: utilities.colors("errorDark").string()
});

export const accountActionsItemDisabledStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-disabled",
  cursor: "not-allowed",
  color: utilities.colors("scorpion").alpha(.3).string()
});

export const accountActionsItemActiveStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-active",
  "&:hover": {
    cursor: "pointer",
    background: utilities.colors("aquaHaze").string()
  }
});

export const accountActionsItemProcessingStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-processing",
  cursor: "not-allowed",
  color: utilities.colors("scorpion").alpha(.3).string()
});

export const accountActionsItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-title",
  ...utilities.fontStyle({
    size: "regular",
    weight: "m"
  })
});

export const accountActionsItemDescriptionStyle: StudioCSS = (theme, utilities) => ({
  label: "account-actions-item-description",
  ...utilities.fontStyle({
    size: "small",
    weight: "n"
  })
});
