import {Styles} from "@dashthis/ui";
import {StudioCSS} from "../../../styles/types";

export const aboutContentStyle: Styles.Types.CSS = (theme, utilities) => ({
  label: "about-content",
  display: "grid",
  gridTemplateColumns: "105px 1fr"
});

export const aboutContentLeftStyle: StudioCSS = (theme, utilities) => ({
  label: "about-content-left",
  background: utilities.colors("primary").string(),
  display: "flex",
  justifyContent: "center",
  alignItems: "flex-start",
  borderTopLeftRadius: 3,
  borderBottomLeftRadius: 3,
  paddingTop: utilities.space("xl")
});

export const aboutContentIconStyle: StudioCSS = (theme, utilities) => ({
  label: "about-content-icon",
  fill: utilities.colors("white").toString(),
  width: 52
});

export const aboutContentTextStyle: StudioCSS = (theme, utilities) => ({
  label: "about-content-text",
  background: utilities.colors("white").string(),
  padding: utilities.space("xl"),
  p: {
    paddingBottom: utilities.space("n")
  },
  strong: {
    ...utilities.fontStyle({weight: "m"})
  },
  "p:nth-child(1)": {
    ...utilities.fontStyle({
      weight: "m",
      size: "huge"
    })
  },
  "p:nth-child(2)": {
    ...utilities.fontStyle({
      weight: "n",
      size: "large"
    })
  },
  "p:nth-child(3)": {
    ...utilities.fontStyle({
      weight: "n",
      size: "regular"
    }),
    paddingBottom: utilities.space("l")
  },
  button: {
    float: "right"
  }
});