import * as React from "react";
import {MouseEventHandler, ReactNode, useCallback, useMemo, useRef} from "react";
import {Hooks} from "@dashthis/ui";
import {Hooks as HooksCommon} from "@dashthis/common";
import {customAlphabet} from "nanoid";
import {NavigationBarContext} from "../context/NavigationBarContext";

const nanoid = customAlphabet("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", 10);

export type NavigationBarOverFlowItem = {
  id: string,
  title: string,
  onClick?: MouseEventHandler,
  top: number,
  element: HTMLDivElement,
  selected: boolean
}
export type NavigationBarOverflow = {
  className: string,
  itemsHide: boolean,
  itemsNotVisible: NavigationBarOverFlowItem[],
  useNavigationBarItemId: () => string,
  registerItem: (id: string, title: string, selected: boolean, onClick: MouseEventHandler | undefined, element: HTMLDivElement) => void,
  toggleItem: (value: boolean, id: string) => void,
  Provider: React.FC<{ children: ReactNode }>
}

const useNavigationBarItemId = (): string => useRef(nanoid()).current;


export const useNavigationBarOverflow = (): NavigationBarOverflow => {
  const forceUpdate = HooksCommon.useForceUpdate();
  const className = useRef(nanoid()).current;
  const items = useRef<Map<string, NavigationBarOverFlowItem>>(new Map<string, NavigationBarOverFlowItem>());
  const {height, top} = Hooks.useObserveBoxOfElement(`.${className}`);
  const registerItem = useCallback<NavigationBarOverflow["registerItem"]>((id, title, selected, onClick, element) => {
    if (!items.current.has(id)) {
      const rect = element.getBoundingClientRect();

      items.current.set(id, {
        id,
        onClick,
        title,
        top: rect.top + rect.height,
        element,
        selected
      });
    }
  }, [items]);
  const itemsNotVisible = useMemo(() => {
    const containerHeight = top + height;
    const itemsAreNotVisible: NavigationBarOverFlowItem[] = [];

    items.current.forEach((i) => {
      if ((i.top - 10) > containerHeight) {
        i.element.style.display = "none";
        itemsAreNotVisible.push(i);
      } else {
        i.element.style.removeProperty("display");
      }
    });

    return itemsAreNotVisible;
  }, [height, top, items.current]);
  const toggleItem = useCallback<NavigationBarOverflow["toggleItem"]>((value, id) => {
    if (items.current.has(id)) {
      const i = items.current.get(id);

      items.current.set(id, {
        ...i!,
        selected: value
      });

      items.current = new Map<string, NavigationBarOverFlowItem>(items.current);
      forceUpdate();
    }
  }, [items, forceUpdate]);
  const Provider = React.useMemo(() => ({children}: { children: ReactNode }) => {
    return <NavigationBarContext.Provider value={{
      toggleItem,
      useNavigationBarItemId,
      registerItem
    }}>
      {children}
    </NavigationBarContext.Provider>;
  }, []);

  return {
    className,
    Provider,
    toggleItem,
    itemsNotVisible,
    itemsHide: itemsNotVisible.length > 0,
    useNavigationBarItemId,
    registerItem
  };
};