import {DTGraphTypes, Models, Search} from "@dashthis/common";
import {DashboardType, DashboardTypeModel} from "./DashboardType";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import calendar from "dayjs/plugin/calendar";
import {Account, AccountModel} from "./Account";
import {isNil} from "lodash";
import {Widget, WidgetModel} from "./Widget";
import {DashboardHealth, DashboardHealthModel} from "./DashboardHealth";

dayjs.extend(calendar);
dayjs.extend(relativeTime);

export interface IDashboard extends DTGraphTypes.Dashboard, Search.Interfaces.IMatchableQuery, Models.Bases.BaseDashboard.IBaseDashboard, Models.Interface.IComparable {
  DashboardType: DashboardTypeModel | undefined;
  Account: AccountModel | undefined;
  Healths: DashboardHealthModel | undefined;
  Widgets: Models.Types.Models<WidgetModel>,
  lastAccessed: string;
  createdAt: string;
  deleteAt: string;
  isProtected: boolean
}

export type DashboardModel = Models.Types.Model<Omit<IDashboard,
  "type"
  | "account"
  | "dateLastAccessed"
  | "creationDate">>;

export const Dashboard: Models.Types.ModelCtr<DTGraphTypes.Dashboard, IDashboard> = (data) => ({
  ...data,
  ...Models.Bases.BaseDashboard.baseDashboard(data),
  get lastAccessed() {
    const lastAccessed = dayjs(data.dateLastAccessed);

    return lastAccessed.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY H:mm a"
    });
  },
  get isProtected() {
    return data.pin != null && data.pin !== "";
  },
  get createdAt() {
    const lastAccessed = dayjs(data.creationDate);

    return lastAccessed.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY H:mm a"
    });
  },
  get deleteAt() {
    const lastAccessed = dayjs(data.dateDeleted);

    return lastAccessed.calendar(undefined, {
      sameDay: "[Today at] H:mm a",
      nextDay: "[Tomorrow]",
      nextWeek: "dddd",
      lastDay: "[Yesterday]",
      lastWeek: "[Last] dddd",
      sameElse: "MMMM D, YYYY H:mm a"
    });
  },
  get Healths() {
    return Models.createModel<DTGraphTypes.DashboardHealth, DashboardHealthModel>(data.healths, DashboardHealth);
  },
  get Widgets() {
    return Models.createModels<DTGraphTypes.Widget, WidgetModel>(data.widgets, Widget);
  },
  get Account() {
    return Models.createModel<DTGraphTypes.Account, AccountModel>(data.account, Account);
  },
  get DashboardType() {
    return Models.createModel<DTGraphTypes.DashboardType, DashboardTypeModel>(data.type, DashboardType);
  },
  areSame(dashboard) {
    if (isNil(dashboard)) {
      return false;
    }

    return data.id!.toLowerCase() === dashboard.id!.toLowerCase();
  }
});