import React, {Fragment, useMemo} from "react";
import {Button, QueryProcessor, Styles, Window} from "@dashthis/ui";
import {DTGraphTypes, Types} from "@dashthis/common";
import formatMessage from "format-message";
import {CsvTemplateModel} from "../../../../../../../../models/CsvTemplate";
import {useGetFileTemplateDetail} from "../../../../../../../../hooks/useGetFileTemplateDetail";
import {AccountModel} from "../../../../../../../../models/Account";
import {fileTemplatesViewEditTitleWindowStyle, fileTemplatesViewEditWindowContentStyle, fileTemplatesViewEditWindowStyle} from "./styles/fileTemplatesViewEditWindow.style";
import ViewEditFileTemplateWindowHeaderSection from "./ViewEditFileTemplateWindowHeaderSection";
import ViewEditFileTemplateWindowSettingSection from "./ViewEditFileTemplateWindowSettingSection";
import ViewEditFileTemplateWindowMetricSection from "./ViewEditFileTemplateWindowMetricSection";
import ViewEditFileTemplateWindowDimensionSection from "./ViewEditFileTemplateWindowDimensionSection";
import {Formik} from "formik";
import {useSaveFileTemplate} from "../../hooks/useSaveFileTemplate";
import {diff} from "deep-diff";
import cleanDeep from "clean-deep";


interface IProps {
  /**
   * The File Template Model.
   */
  fileTemplate: CsvTemplateModel;
  /**
   * Callback to call for closing window
   */
  close: () => void;
  /**
   * The account model
   */
  account: AccountModel;
}

export interface IFileTemplateValues extends DTGraphTypes.FileTemplateInputType {
}

const cleanOption = {
  emptyStrings: false,
  nullValues: false
};
const canSubmit = (initialValues: IFileTemplateValues, changeValues: IFileTemplateValues, isValid: boolean): boolean => {
  const changes = diff(initialValues, cleanDeep(changeValues, cleanOption));

  return !!changes && isValid;
};

export const ViewEditFileTemplateWindow = (props: IProps) => {
  const {fileTemplate, close, account} = props;
  const {processing, updateFileTemplate} = useSaveFileTemplate(account.id!);
  const [detailedFiledTemplate, loading, error] = useGetFileTemplateDetail(fileTemplate.id!, account.id!);
  const css = Styles.Hooks.useClassName(fileTemplatesViewEditWindowStyle);
  const contentCss = Styles.Hooks.useClassName(fileTemplatesViewEditWindowContentStyle);
  const titleCss = Styles.Hooks.useClassName(fileTemplatesViewEditTitleWindowStyle);
  const windowSize: Types.Geometry.Size = {
    width: "70%",
    height: "70%"
  };
  const initialValues: IFileTemplateValues = useMemo(() => ({
    name: detailedFiledTemplate.name,
    id: detailedFiledTemplate.id,
    dateRangeSeparator: detailedFiledTemplate.dateRangeSeparator,
    encoding: detailedFiledTemplate.encoding,
    separator: detailedFiledTemplate.separator,
    footerLines: detailedFiledTemplate.footerLines,
    headerLines: detailedFiledTemplate.headerLines,
    dataFields: detailedFiledTemplate.Fields.map((f) => ({
      dataFormat: f.dataFormat,
      decimals: f.decimals,
      id: f.id,
      name: f.name
    }))
  }), [detailedFiledTemplate]);

  return (
    <Window.Window onClose={close} size={windowSize} title={formatMessage("File template : {name}", {
      name: fileTemplate.name
    })}>
      <div className={css}>
        <QueryProcessor.QueryProcessor loading={loading} error={error}>
          <div className={titleCss}>
            <strong>{formatMessage("Template name :")}</strong>{detailedFiledTemplate.name}
          </div>
          <Formik initialValues={initialValues} onSubmit={async (values) => {
            await updateFileTemplate(values);
          }}>
            {({isValid, submitForm, values}) => {
              return (
                <Fragment>
                  <Window.Content scrollable className={contentCss} padding={0}>
                    <ViewEditFileTemplateWindowHeaderSection csvTemplate={detailedFiledTemplate}/>
                    <ViewEditFileTemplateWindowSettingSection csvTemplate={detailedFiledTemplate}/>
                    <ViewEditFileTemplateWindowMetricSection csvTemplate={detailedFiledTemplate}/>
                    <ViewEditFileTemplateWindowDimensionSection csvTemplate={detailedFiledTemplate}/>
                  </Window.Content>
                  <Window.Footer>
                    <Button.Button onClick={close} basic={false}>{formatMessage("Close")}</Button.Button>
                    <Button.Button onClick={submitForm} loading={processing} disabled={!canSubmit(initialValues, values, isValid)} basic={false}>{formatMessage("Save")}</Button.Button>
                  </Window.Footer>
                </Fragment>
              );
            }}
          </Formik>
        </QueryProcessor.QueryProcessor>
      </div>
    </Window.Window>
  );
};

export default ViewEditFileTemplateWindow;
