import React from "react";
import {Spinner, Styles} from "@dashthis/ui";
import {searchBarFooterEnterKeyStyle, searchBarFooterKeysStyle, searchBarFooterSpinnerStyle, searchBarFooterStyle} from "./styles/searchBarFooter.style";

type Props = {
  /**
   * Set to true to display the spinner.
   */
  loading: boolean
};

export const Footer = (props: Props) => {
  const {loading} = props;
  const footerCss = Styles.Hooks.useClassName(searchBarFooterStyle);
  const keyCss = Styles.Hooks.useClassName(searchBarFooterEnterKeyStyle);
  const keysCss = Styles.Hooks.useClassName(searchBarFooterKeysStyle);
  const spinnerCss = Styles.Hooks.useClassName(searchBarFooterSpinnerStyle);

  return (
    <div className={footerCss}>
      <div className={keysCss}>
        <span className={keyCss}>↵</span> to search
      </div>
      <div className={keysCss}>
        <span className={keyCss}>esc</span> to dismiss
      </div>
      {loading ? <Spinner.Wheel className={spinnerCss}/> : null}
    </div>
  );
};


export default Footer;
