import React from "react";
import {Styles} from "@dashthis/ui";
import {Models} from "@dashthis/common";
import {accountPlanActionsPlanCountStyle, accountPlanActionsPlanNameStyle, accountPlanActionsPlanPriceStyle, accountPlanActionsPlanStyle} from "./styles/AccountPlanActionsPlan.style";
import formatMessage from "format-message";

interface IProps {
  /**
   * Component children.
   */
  plan: Models.Plan.PlanModel;
}

export const AccountPlanActionsPlan = (props: IProps) => {
  const {plan} = props;
  const css = Styles.Hooks.useClassName(accountPlanActionsPlanStyle);
  const nameCss = Styles.Hooks.useClassName(accountPlanActionsPlanNameStyle);
  const dashboardCss = Styles.Hooks.useClassName(accountPlanActionsPlanCountStyle);
  const priceCss = Styles.Hooks.useClassName(accountPlanActionsPlanPriceStyle);

  return (
    <div className={css}>
      <p className={nameCss}>{plan.name}</p>
      <p className={dashboardCss}>{plan.nbDashboards} {formatMessage("Dashboards")}</p>
      <p className={priceCss}>{plan.Price()}</p>
    </div>
  );
};


export default AccountPlanActionsPlan;
