import React from "react";
import {CsvSourceModel} from "../../../../../../../models/CsvSource";
import formatMessage from "format-message";
import {Styles} from "@dashthis/ui";
import {fileTemplatesItemDetailStyle, fileTemplatesItemDetailStyleLabelStyle} from "./styles/fileTemplatesItemDetail.style";

interface IProps {
  /**
   * The source model.
   */
  source: CsvSourceModel;
}

export const FileTemplatesSourceDetail = (props: IProps) => {
  const {source} = props;
  const css = Styles.Hooks.useClassName(fileTemplatesItemDetailStyle);
  const labelCss = Styles.Hooks.useClassName(fileTemplatesItemDetailStyleLabelStyle);

  return (
    <div className={css}>
      <label className={labelCss}>{formatMessage("Id")} <span>: {source.id}</span></label>
      <label className={labelCss}>{formatMessage("Name")} <span>: {source.name}</span></label>
      <label className={labelCss}>{formatMessage("Provider Key")} <span>: {source.providerKey}</span></label>
    </div>
  );
};


export default FileTemplatesSourceDetail;