import {StudioCSS} from "../../../../../../../styles/types";

export const accountUsersItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item",
  display: "grid",
  gridTemplateColumns: "1fr auto",
  padding: utilities.space("s"),
  alignItems: "center",
  "&:hover": {
    cursor: "pointer"
  },
  backgroundColor: utilities.colors("white").string()
});

export const accountUsersItemSelectedStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item-selected",
  backgroundColor: utilities.colors("chambray").alpha(.4).string()
});

export const accountUsersItemEmailStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item-email",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "regular",
    weight: "n",
    color: "primary"
  })
});

export const accountUsersItemNameStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item-name",
  ...utilities.ellipsis(),
  ...utilities.fontStyle({
    size: "small",
    weight: "l",
    color: "scorpion"
  })
});

export const accountUsersItemGravatarContainerStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item-gravatar-container",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  gridTemplateRows: "auto",
  alignSelf: "flex-start",
  marginRight: utilities.space("s")
});

export const accountUsersItemGravatarStyle: StudioCSS = (theme, utilities) => ({
  label: "account-users-item-gravatar",
  marginRight: utilities.space("s"),
  width: 30,
  height: 30,
  alignSelf: "center",
  gridColumn: 1,
  gridRow: "1 / 3"
});

export const accountUsersItemButtonGroupStyle: StudioCSS = (theme, utilities) => ({
  display: "flex",
  paddingLeft: utilities.space.normal
});
