import {useEventServiceContext} from "../../../services/hooks/useEventServiceContext";
import {useEffect} from "react";
import {Enums} from "@dashthis/studio-common";

export const useOnEmulateSettings = (handler: () => void) => {
  const eventService = useEventServiceContext();

  useEffect(() => {
    eventService.on(Enums.IPCChannelEnum.ShowEmulateSetting, handler);

    return () => {
      eventService.removeListener(Enums.IPCChannelEnum.ShowEmulateSetting, handler);
    };
  }, [eventService]);
};