import {StudioCSS} from "../../../../../../../styles/types";

export const accountPlanActionsItemStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item",
  padding: utilities.space("n"),
  "&:nth-of-type(odd)":{
    background: utilities.colors("white").string()
  },
  "&:nth-of-type(even)":{
    background: utilities.colors("aquaHazeLight").string()
  }
});


export const accountPlanActionsItemTitleStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item-title",
  textTransform: "uppercase",
  ...utilities.fontStyle({
    color: "primary",
    size: "regular",
    weight: "b"
  })
});

export const accountPlanActionsItemDescriptionStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item-description",
  ...utilities.fontStyle({
    color: "primary",
    size: "regular",
    weight: "n"
  }),
  paddingBottom: utilities.space("n")
});

export const accountPlanActionsItemButtonsStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item-buttons",
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  alignItems: "center",
  gap: utilities.space("s")
});

export const accountPlanActionsItemErrorStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item-error",
  color: utilities.colors("error").string(),
  display: "grid",
  gridTemplateColumns: "auto 1fr",
  alignItems: "center",
  span: {
    textTransform:"uppercase",
    ...utilities.fontStyle({
      size:"tiny"
    })
  }
});

export const accountPlanActionsItemErrorIconStyle: StudioCSS = (theme, utilities) => ({
  label: "account-plan-actions-item-error-icon",
  width: 26,
  fill: "currentcolor"
});
