import {Client, DTGraphTypes, Types} from "@dashthis/common";
import {Services, Notification} from "@dashthis/ui";
import React, {useCallback, useEffect, useMemo, useRef} from "react";
import {forceUserPasswordMutation} from "../queries/user/forcePassword.mutation";
import formatMessage from "format-message";

type ForceUserPasswordResponseMatcher<R> = {
  onForceUserPasswordError: (e: Client.Errors.ApplicationServerError) => R,
  onForceUserPasswordProcessing: () => R,
  onForceUserPasswordComplete: () => R,
  onForceUserStandby: () => R
}

type ForceUserPassword = {
  matcher: <R>(matcher: ForceUserPasswordResponseMatcher<R>) => R,
  forcePassword: (password: string, userId: string) => Promise<void>
}

type Response = {
  userForcePassword: DTGraphTypes.User
}
type Variables = {
  password: string,
  userId: string
};

const matchResponse = <R, >(response: Response, error: Types.Utilities.Nillable<Client.Errors.ApplicationServerError>, processing: boolean, matcher: ForceUserPasswordResponseMatcher<R>) => {
  if (error != null) {
    return matcher.onForceUserPasswordError(error);
  }

  if (!processing && response?.userForcePassword != null) {
    return matcher.onForceUserPasswordComplete();
  }

  if (processing) {
    return matcher.onForceUserPasswordProcessing();
  }

  return matcher.onForceUserStandby();
};


export const useForceUserPassword = (): ForceUserPassword => {
  const [execute, {processing, error, data}] = Client.Hooks.useMutation<Response, Variables>(forceUserPasswordMutation);
  const hideToastNotification = useRef<() => void | undefined>();
  const forcePassword = useCallback<ForceUserPassword["forcePassword"]>(async (password, userId) => {
    await execute({
      variables: {
        password,
        userId
      }
    });
  }, []);

  useEffect(() => {
    matchResponse(data, error, processing, {
      onForceUserPasswordComplete: () => {
        hideToastNotification.current?.();
        Services.toastNotificationService.display(<Notification.SuccessNotification>{formatMessage("The new password has been applied.")}</Notification.SuccessNotification>);
      },
      onForceUserPasswordError: (e) => {
        hideToastNotification.current?.();
        Services.clientService.Error.displayError(e);
      },
      onForceUserPasswordProcessing: () => {
        hideToastNotification.current = Services.toastNotificationService.displaySticky(<Notification.LoadingNotification>{formatMessage("Applying a new password...")}</Notification.LoadingNotification>);
      },
      onForceUserStandby: () => {
        //
      }
    });
  }, [error, processing]);

  return useMemo(() => ({
    forcePassword,
    matcher: (matcher) => matchResponse(data, error, processing, matcher)
  }), [processing, error, data]);
};