import React from "react";
import {Icon, Stack, Styles} from "@dashthis/ui";
import {Client} from "@dashthis/common";
import {applicationErrorDescriptionStyle, applicationErrorIconStyle, applicationErrorStyle, applicationErrorTitleStyle} from "./styles/applicationError.style";
import formatMessage from "format-message";

interface IProps {
  title?: string;
  error: Client.Errors.ApplicationServerError;
}

export const ApplicationError = (props: IProps) => {
  const {error, title = formatMessage("An error has occurred.")} = props;
  const css = Styles.Hooks.useClassName(applicationErrorStyle);
  const iconCss = Styles.Hooks.useClassName(applicationErrorIconStyle);
  const titleCss = Styles.Hooks.useClassName(applicationErrorTitleStyle);
  const descriptionCss = Styles.Hooks.useClassName(applicationErrorDescriptionStyle);

  return (
    <div className={css}>
      <Stack.HStack gap={10} alignItems={Stack.Enums.AlignItemsEnum.Center}>
        <Stack.StackItem className={iconCss} as={Icon.Icons.AttentionFullIcon} itemSize="auto"/>
        <Stack.StackItem as="div" itemSize="1fr">
          <p className={titleCss}>{title}</p>
          <p className={descriptionCss}>{error.message}</p>
        </Stack.StackItem>
      </Stack.HStack>
    </div>
  );
};

export default ApplicationError;
